NAME = 'RusMakarij: The Pentateuch of Moses in Russian'
BOOK = 'Deuteronomy'

CHAPTERS = {
    1: {
        1: 'Сіи суть слова, которыя говорилъ Моисей всјмъ Израильтянамъ за Іорданомъ, въ пустынј на равнинј близъ Суфа, между Фараномъ, и Тофеломъ, и Лававомъ, и Асироѕомъ и Дизагавомъ,',
        2: 'въ разстояніи одиннадцати дней пути оть Хорива, на дорогј отъ горы Сеиръ, къ Кадесъ-Варни.',
        3: 'Сороковаго года, одиннадцатаго мјсяца, въ первый день мјсяца говорилъ Моисей сынамъ Израилевымъ все, что повелјлъ ему Господь сказать имъ.',
        4: 'По убіеніи Сигона, царя Аморрейскаго, который жилъ въ Есевонј, и Ога, царя Васанскаго, который жилъ въ Аштероѕј въ Едреи,',
        5: 'за Іорданомъ, въ землј Моавитской, началъ Моисей изъяснять законъ сей, и сказалъ:',
        6: 'Господь, Богъ нашъ, говорилъ намъ на Хоривј, и скавалъ: полно вамъ пребывать на горј сей,',
        7: 'обратитесь, отправьтесь въ путь и подите на гору Аморрейскую и во всј сосјдственныя съ нею земли, на равнину, на гору, на низкія мјста и на южный край и къ берегамъ моря, въ землю Ханаанскую и къ Ливану, даже до рјки великой, рјки Ефрата.',
        8: 'Вотъ, Я даю вамъ землю сію, подите, возьмите въ наслјдіе землю, которую Господь съ клятвою објщалъ дать отцамъ вашимъ, Аврааму, Исааку и Іакову, имъ и потомству ихъ послј нихъ.',
        9: 'И я сказалъ вамъ въ то время: не могу одинъ носить васъ;',
        10: 'Господь, Богъ вашъ, размножилъ васъ, и вотъ, вы нынј многочисленны, какъ звјзды небесныя.',
        11: '(Господь, Богъ отцевъ вашихъ, да умножитъ васъ въ тысячу кратъ противъ того, сколько васъ теперъ, и да благословитъ васъ, какъ онъ говорилъ вамъ!)',
        12: 'Какъ же мнј одному носить тягости ваши, бремена ваши и распри ваши?',
        13: 'Изберите себј по колјнамъ вашимъ мужей мудрыхъ, разумныхъ и испытанныхъ, и я поставлю ихъ начальниками вашими.',
        14: 'Вы отвјчали мнј и сказали: хорошее дјло велишь ты сдјлать.',
        15: 'И взялъ я главныхъ изъ колјнъ вашихъ, мужей мудрыхъ и испытанныхъ, и сдјлалъ ихъ началъниками надъ вами, тысяченальниками, стоначальниками, пятидесятиначальниками, десятиначальниками и надзирателями по колјнамъ вашимъ.',
        16: 'И далъ я повелјніе судьямъ вашимъ въ то время, и сказалъ: выслушивайте братьевъ вашихъ и судите справедливо, какъ брата съ братомъ, такъ и пришельца его.',
        17: 'Не различайте лицъ на судј; какъ малаго, такъ и великаго выслушивайте, не бойтесь лица человјческаго: ибо это судъ Божій; а дјло, которое для васъ трудно, доводите до меня, я выслушаю его.',
        18: 'Такимъ образомъ я далъ вамъ въ то время повелјнія обо всемъ, что надлежало дјлать.',
        19: 'И отправились мы отъ Хорива и шли по всей оной великой и страшной пустынј, которую вы видјли, направляя путь къ горј Аморрейской, какъ повелјлъ Господь, Богъ нашъ, и пришли въ Кадесъ-Варни.',
        20: 'И сказалъ я вамъ: вы пришли къ горј Аморрейской, которую Господь, Богъ нашъ, даетъ намъ.',
        21: 'Вотъ, Господь, Богъ твой, предаетъ тебј землю сію, иди, возьми въ наслјдіе, какъ говорилъ тебј Господь, Богъ отцевъ твоихъ, не бойся и не ужасайся.',
        22: 'Но вы всј подошли ко мнј, и сказали: пошлемъ передъ собою людей, чтобъ они изслјдовали намъ землю, и принесли намъ извјстіе, какою дорогою идти намъ и въ какіе города идти намъ.',
        23: 'Слово сіе мнј понравилось, и я взялъ изъ васъ двјнадцать человјкъ, по одному человјку отъ колјна.',
        24: 'Они пошли, взошли на гору и дошли до долины Есхолъ и обозрјли ее.',
        25: 'И взяли въ руки свои плодовъ земли и доставили намъ, и принесли намъ извјстіе, и сказали: земля, которуюГосподь, Богъ нашъ, даетъ намъ, хороша.',
        26: 'Но вы не захотјли идти и воспротивились повелјнію Господа, Бога вашего,',
        27: 'и роптали въ шатрахъ вашихъ, и говорили: Господъ, по ненависти къ намъ, вывелъ насъ изъ земли Египетской, чтобъ отдать насъ въ руки Аморреевъ и истребить насъ.',
        28: 'Куда мы идемъ? Братья наши разслабили сердце наше, говоря: народъ тотъ болје и выше насъ, города тамъ большіе и съ укрјпленіями, возвышающимися до небесъ, да и сыновъ Енаковыхъ видјли мы тамъ.',
        29: 'Тогда сказалъ я вамъ: не страшитесь и не бойтесь ихъ.',
        30: 'Господь, Богъ вашъ, идетъ передъ вами, Онъ будетъ сражаться за васъ, такъ какъ Онъ сіе дјлалъ съ вами въ Египтј предъ глазами вашими,',
        31: 'и въ пустынј сей, гдј, какъ ты видјлъ, Господь, Богь твой, носилъ тебя, какъ человјкъ носитъ сына своего, на всемъ пути, которымъ вы проходили, до самаго пришествія вашего на сіе мјсто.',
        32: 'Но несмотря на сіе вы не вјровали Господу, Богу вашему,',
        33: 'Который шелъ передъ вами путемъ искать вамъ мјста, гдј остановиться вамъ, ночью въ огнј, чтобъ указывать вамъ дорогу, по которой идти, а днемъ въ облакј.',
        34: 'Господь услышалъ шумъ словъ вашихъ, и вознегодовалъ, и поклялся, говоря:',
        35: 'никто изъ людей сихъ, изъ сего злаго рода, не увидитъ доброй оной земли, которую Я клялся дать отцамъ ыашимъ.',
        36: 'Только Халевъ, сынъ Іефонніинъ, увидитъ ее; ему дамъ Я землю, по которой онъ проходилъ, и сынамъ его, за то, что онъ совершенно послјдовалъ Господу.',
        37: 'И на меня прогнјвался Господь за васъ, говоря: и ты не войдешь туда.',
        38: 'Іисусъ, сынъ Навинъ, который предстоитъ тебј, онъ войдетъ туда, его утверди; ибо онъ раздјлитъ ее на удјлы Израилю.',
        39: 'Дјти ваши, о которыхъ вы говорили, что они достанутся въ добычу врагамъ, и сыновья ваши, которые не знаютъ нынј ни добра ни зла, они войдутъ туда, имъ дамъ ее и они получатъ ее въ наслјдіе;',
        40: 'а вы возвратитесь и отправьтесь въ пустыню къ Чермному морю.',
        41: 'Вы отвјчали тогда, и сказали мнј: согрјшили мы предъ Господомъ, пойдемъ и сразимся, какъ повелјлъ намъ Господь, Богъ нашъ; и препоясались каждый ратнымъ оружіемъ своимъ и безразсудно взошли на гору.',
        42: 'Но Господь скавалъ мнј: скажи имъ: не восходите и не сражайтесь, потому что нјтъ Меня среди васъ, чтобы не поразили васъ враги ваши.',
        43: 'Я вамъ говорилъ, но вы не послушали и воспротивились повелјнію Господню, и по упорству своему взошли на гору.',
        44: 'И выступилъ противъ васъ Аморрей, живущій на горј той, и гнались за вами, такъ какъ дјлаютъ пчелы, и били васъ на Сеирј до самой Хормы.',
        45: 'Возвратившись вы плакали предъ Господомъ; но Господь не услышалъ вопля вашего и не внялъ вамъ.',
        46: 'Такимъ образомъ пробыли вы въ Кадесј много времени, сколько времени вы тамъ были.',
    },
    2: {
        1: 'Потомъ мы обратились и отправились въ пустыню къ Чермному морю, какъ говорилъ мнј Господь, и много времени ходили вокругъ горы Сеира.',
        2: 'И сказалъ мнј Господь:',
        3: 'полно вамъ ходить вокругъ этой горы, обратитесь къ сјверу.',
        4: 'И народу дай повелјніе, и скажи: вы будете проходить предјлы братій вашихъ, сыновъ Исавовыхъ, живущихъ на Сеирј, и они убоятся васъ, но остерегайтесь',
        5: 'всячески начинать съ ними войну; ибо Я не дамъ вамъ земли ихъ ни на стопу ноги, потому что гору Сеиръ Я далъ въ наслјдіе Исаву.',
        6: 'Хлјбъ для прокормленія покупайте у нихъ за сребро, и воду для питья покупайте у нихъ за сребро:',
        7: 'ибо Господь, Богъ твой, благословилъ тебя во всякомъ дјлј рукъ твоихъ, покровительствовалъ тебј во время шествія твоего по великой пустынј сей; вотъ, сорокъ лјтъ Господь, Богъ твой, съ тобою, ты ни въ чемъ не терпјлъ недостатка.',
        8: 'И шли мы мимо братій нашихъ, сыновъ Исавовыхъ; живущихъ на Сеирј, путемъ равнины, отъ Елаѕа и Еціонъ-Гавера, и обратились и шли къ пустынј Моава.',
        9: 'Тогда Господь сказалъ мнј: не вступай во вражду съ Моавомъ и не начинай съ ними войны; ибо Я не дамъ тебј земли его въ наслјдіе, потому что Аръ отдалъ Я въ наслјдіе сынамъ Лотовымъ.',
        10: '(Прежде жили тамъ Емимы, народъ великій, многочисленный и высокій, какъ сыны Енаковы;',
        11: 'и они считались между Рефаимами, какъ сыны Енаковы; Моавитяне же называютъ ихъ Емимами.',
        12: 'А на Сеирј жили прежде Хорреи; но сыны Исавовы прогнали ихъ и истребили ихъ отъ лица своего, и поселились на мјстј ихъ, такъ, какъ поступилъ Израиль съ землею наслјдія своего, которую далъ имъ Господь).',
        13: 'Итакъ встаньте и пройдите долину Заредъ. И прошли мы долииу Заредъ.',
        14: 'Съ тјхъ поръ, какъ мы пошли изъ Кадесъ-Варни, до тјхъ поръ, какъ мы прошли долину Заредъ, прошло тридцать восемь лјтъ, какъ наконецъ перевелся изъ среды стана весь родъ ходящихъ на войну, какъ Господь клялся имъ.',
        15: 'Да и рука Господня была на нихъ, чтобы истреблять ихъ изъ среды стана, пока не перевелись.',
        16: 'Когда же перевелись всј ходящіе на войну и перемерли изъ среды народа,',
        17: 'тогда говорилъ мнј Господь, и сказалъ:',
        18: 'ты проходишь нынј мимо предјловъ Моава, мимо Ара,',
        19: 'и приблизился къ сынамъ Аммоновымъ; не вступай съ ними во вражду и не начинай съ ними войны; ибо Я не дамъ тебј земли сыновъ Аммоновыхъ въ наслјдіе, потому что Я отдалъ ее въ наслјдіе сынамъ Лотовымъ.',
        20: '(И она считается землею Рефаимовъ, прежде жили на ней Рефаимы, Амионитяне же называютъ ихъ Замзуммимами.',
        21: 'Народъ великій, многочисленный и высокій, какъ сыны Енаковы, и истребилъ ихъ Господь предъ лицемъ ихъ, и изгнали они ихъ, и поселились на мјстј ихъ,',
        22: 'такъ, какъ Онъ сдјлалъ для сыновъ Исавовыхх, живущихъ на Сеирј, истребивъ предъ лицемъ ихъ Хорреевъ, и они изгнали ихъ, и поселились на мјстј ихъ и живутъ до сего дня;',
        23: 'и такъ, какъ Аввеевъ, жившихъ въ селеніяхъ до самой Газы, Кафторяне, пришедшіе изъ Кафтора, истребили и поселились на мјстј ихъ.)',
        24: 'Встаньте, отправьтесь и перейдите потокъ Арнонъ; вотъ, Я предаю въ руку твою Сигона, царя Есевонскаго, Аморреянина, и землю его, начинай брать наслјдіе и веди съ нимъ войну.',
        25: 'Съ сего дня я начну распространять страхъ твой и ужасъ твой на народы подъ всјмъ небомъ; тј, которые услышатъ о тебј, вострепещутъ и ужаснутся тебя.',
        26: 'И послалъ я пословъ изъ пустыни Кедемоѕъ къ Сигону, царю Есевонскому, съ словами мирными, чтобъ сказать:',
        27: 'позволь пройдти мнј землею твоею, я пойду дорогою, не сойду ни на право ни на лјво;',
        28: 'хлјбъ для прокормленія продавай мнј за сребро, и воду для питья давай мнј за сребро, только ногами моими пройду:',
        29: 'такъ, какъ сдјлали мнј сыны Исава, живущіе на Сеирј, и Моавитяие, живущіе въ Арј, пока не перейду чрезъ Іорданъ въ землю, которую Господь, Богъ нашъ, даетъ намъ.',
        30: 'Но Сигонъ, царь Есевонскій, не согласился позволить пройдти намъ черезъ свою землю, потому что Господь, Богъ твой, ожесточилъ духъ его, и сердце его сдјлалъ упорнымъ, чтобы предать его въ руку твою, какъ это видно нынј.',
        31: 'Тогда сказалъ мнј Господь: се, Я начинаю предавать тебј Сигона и землю его; начинай брать наслјдіе, взявъ въ наслјдіе землю его.',
        32: 'Сигонъ со всјмъ народомъ своимъ выступилъ противъ насъ на сраженіе къ Іаацј.',
        33: 'И предалъ его предъ нами Господь, Богъ нашъ, и мы поразили его и сыновъ его и весь народъ его;',
        34: 'и взяли въ то время всј города его, и предали заклятію всј города, мужчинъ и женщинъ и дјтей, не оставили никого въ живыхъ.',
        35: 'Только взяли мы себј въ добычу скотъ ихъ и захваченное во взятыхъ нами городахъ.',
        36: 'Отъ Ароира, который на берегу потока Арнона, и отъ города, который на долинј до Галаада, не было города, который бы неприступенъ былъ для насъ: все предалъ предъ нами Господь, Богъ нашъ.',
        37: 'Только къ землј сыновъ Аммоновыхъ ты не подходилъ, ни къ мјстамъ близъ потока Іавока, ни къ городамъ, которые на горј, и ни къ чему такому, къ чему не повелјлъ Господь, Богъ нашъ.',
    },
    3: {
        1: 'Обратившись оттуда, шли мы къ Васану, и выступилъ противъ насъ на войну Огъ, царь Васанскій, со всјмъ народомъ своимъ къ Едреи.',
        2: 'И сказалъ мнј Господь: не бойся его; ибо Я отдалъ его въ руку твою, его и весь народъ его и землю его, и ты поступишь съ нимъ такъ, какъ поступилъ съ Сигономъ, царемь Аморрейскимъ, который жилъ въ Есевонј.',
        3: 'И предалъ Господь, Богъ нашъ, въ руку нашу еще и Ога, царя Васанскаго, и весь народъ его; и мы поразили его, такъ что никого не осталось у него въ живыхъ.',
        4: 'И взяли мы въ то время всј города его; не было города, котораго бы мы не взяли у нихъ: шестьдесятъ городовъ, всю область Арговъ, царство Ога Васанскаго.',
        5: 'Всј сіи города укрјплены были высокими стјнами, воротами и запорами, кромј городовъ открытыхъ, коихъ было весьма много.',
        6: 'И предали мы ихъ заклятію, такъ, какъ поступили съ Сигономъ, царемъ Есевонскимъ, предавъ заклятію всякій городъ съ мужчинами, женщинами и дјтьми.',
        7: 'Но весь скотъ и захваченное въ городахъ взяли себј въ добычу.',
        8: 'Такимъ образомъ взяли мы въ то время изъ руки двухъ царей Аморрейскихъ землю сію, которая по сю сторону Іордана, отъ потока Арнона до горы Ермона,',
        9: '(Сидоняне Ермонъ называютъ Ширіономъ, а Аморреи называштъ его Сениромъ),',
        10: 'всј города на равнинј, весь Галаадъ и весь Васанъ до Салхи и Едреи, города царства Ога Васанскаго.',
        11: 'Ибо только Огь, царь Васанскій, оставался изъ Рефаимовъ. Вотъ, одръ его, одръ желјзный, не находится ли и теперь въ Раббј, у сыновъ Аммоновыхъ? длина его девять локтей, а ширина его четыре локтя, локтей мужескихъ.',
        12: 'Землю сію взяли мы въ то время въ наслјдіе, начиная отъ Ароира, который у потока Арнона; и половину горы Галаада съ городами ея отдалъ я колјну Рувимову и Гадову.',
        13: 'А остатокъ Галаада и весь Васанъ, царство Ога, отдалъ я половинј колјна Манассіина, всю область Арговъ со всјмъ Васаномъ (она называется землею Рефаимовъ).',
        14: 'Іаиръ, сынъ Манассіинъ, взялъ всю область Арговъ, до предјловъ Гессурскихъ и Маахскихъ, и назвалъ Васанъ, по имени своему, Селеніями Іаировыми (они называются такъ до сего дня).',
        15: 'Махиру далъ я Галаадъ;',
        16: 'а колјну Рувимову и Гадову далъ, отъ Галаада до потока Арнона, землю между потокомъ и предјломъ, до потока Іавока, предјла сыновъ Аммоновыхъ,',
        17: 'равнину и Іорданъ, который и естъ предјлъ, отъ Киннерета до моря, равнины моря Соленаго, при подошвј горы Фасги къ востоку.',
        18: 'И далъ я вамъ въ то время повелјніе, и сказалъ: Господь, Богъ вашъ, далъ вамъ землю сію въ наслјдіе, но всј способные къ войнј, вооружившись, идите впереди братьевъ своихъ, сыновъ Израилевыхъ;',
        19: 'только жены ваши и дјти ваши и скотъ вашъ (ибо я знаю, что скота у васъ много), пусть останутся въ городахъ вашихъ, которые я далъ вамъ.',
        20: 'Доколј Господь не упокоитъ братьевъ вашихъ, какъ васъ, доколј и они не получатъ въ наслјдіе землю, которую Господь, Богъ вашъ, дастъ имъ за Іорданомъ; тогда возвратитесь всякъ въ свое наслјдіе, которое я далъ вамъ.',
        21: 'И Іисусу заповјдалъ я въ то время, и сказалъ: глаза твои видјли все, что сдјлалъ Господь, Богъ вашъ, двумъ царямъ симъ: тоже сдјлаетъ Господь всјмъ царствамъ, которыя ты будешь проходить.',
        22: 'Не бойтесь ихъ; ибо Господь, Богъ вашъ, Самъ сражается за васъ.',
        23: 'И молился я Господу въ то время, говоря:',
        24: 'Господи, Господи! Ты началъ показывать рабу Твоему величіе Твое, и крјпкую руку Твою: ибо какой Богъ есть на небј, или на земли, который бы могъ сдјлать такія дјла, какія Ты, и съ могуществомъ такимъ, какъ Твое?',
        25: 'Дай мнј перейдти и увидјть оную добрую землю, которая за Іорданомъ, и прекрасную оную гору и Ливанъ.',
        26: 'Но Господь гнјвался на меня за васъ и не послушалъ меня, и сказалъ мнј Господь: полно тебј, впредь не говори Мнј еще такого слова.',
        27: 'Взойди на вершину Фазги, и взгляни очами твоими къ морю, и къ сјверу, и къ югу, и къ востоку, и посмотри очами твоими; потому что ты не перейдешь за Іорданъ сей.',
        28: 'И дай наставленіе Іисусу, и укрјпи его, и утверди его; поелику онъ перейдетъ предъ народомъ симъ, и онъ сдјлаетъ ихъ наслјдниками земли, на которую ты посмотришь.',
        29: 'И остановились мы на долинј, напротивъ Беѕ-Пеора.',
    },
    4: {
        1: 'И нынј, Израиль, слушай постановленія и законы, которые Я научаю васъ исполнять, дабы вы были живы, и пошли и наслјдовали ту землю, которую Господь, Богъ отцевъ вашихъ, даетъ вамъ.',
        2: 'Не прибавляйте къ тому, что Я заповјдаю вамъ, и не убавляйте отъ того; соблюдайте заповјди Господа, Бога вашего, которыя я вамъ заповјдаю.',
        3: 'Глаза ваши видјли, что Господь сдјлалъ за Ваал-Пеора: всякаго человјка, послјдовавшаго Ваал-Пеору, истребилъ Господь, Богъ твой, изъ среды тебя;',
        4: 'а вы, прилјпившіеся къ Господу, Богу вашему, живы всј донынј.',
        5: 'Вотъ, я научилъ васъ постановленіямъ и законамъ, какъ повелјлъ мнј Господь, Богъ мой, дабы вы такъ поступали въ той землј, въ которую вы вступаете, чтобы взять ее въ наслјдіе.',
        6: 'Итакъ храните ихъ, и исполняйте ихъ; ибо сіе есть мудрость ваша и разумъ вашъ предъ глазами народовъ, которые, услышавъ о всјхъ сихъ постановленіяхъ, скажутъ: только сей великій народъ есть народъ мудрый и разумный.',
        7: 'Ибо есть ли какой великій народъ, къ которому боги были бы столь близки, какъ близокъ къ намъ Господь, Богъ нашъ, когда ни призовемъ Его?',
        8: 'Или есть ли какой великій народъ, у котораго были бы такія справедливыя постановленія и законы, какъ весь законъ сей, который я предлагаю вамъ сегодня?',
        9: 'Только берегись и тщательно храни душу твою, чтобы тебј не забыть тјхъ дјлъ, которыя видјли глаза твои, и дабы они не выходили изъ сердца твоего во всј дни жизни твоей, и дай объ нихъ знать сынамъ твоимъ и сынамъ сыновъ твоихъ.',
        10: 'Въ тотъ день, въ который ты стоялъ предъ Господомъ, Богомъ твоимъ, при Хоривј, когда сказалъ мнј Господь: собери ко Мнј народъ, и Я возвјщу имъ слова Мои, изъ которыхъ они научатся бояться Меня во всј дни жизни своей на землј и научатъ сыновъ своихъ;',
        11: 'вы приблизились и стали подъ горою, и гора горјла огнемъ до самыхъ небесъ, и была тьма, облако и мракъ.',
        12: 'И говорилъ Господь къ вамъ изъ среды огня; гласъ словъ вы слышали, но образа не видјли, а только гласъ.',
        13: 'И объявилъ вамъ завјтъ Свой, который велјлъ вамъ исполнять, то-естъ, десять оныхъ словъ, и написалъ ихъ на двухъ скрижаляхъ каменныхъ.',
        14: 'И повелјлъ мнј Господь въ то время научить васъ постановленіямъ и законамъ, дабы вы исполняли ихъ въ той землј, въ которую вы переходите, чтобы взять ее въ наслјдіе.',
        15: 'Твердо держите сіе въ душахъ вашихъ, что вы не видјли никакого образа въ тотъ день, когда говорилъ къ вамъ Господь на Хоривј изъ среды огня,',
        16: 'дабы вы не развратились и не сдјлали себј кумировъ, изображеній какого-либо вида, представляющихъ мужчину или женщину,',
        17: 'представляющихъ какого-либо скота, который на землј, представляющихъ какую-либо птицу крылатую, которая летаетъ подъ небесами,',
        18: 'представляюшихъ какого-либо гада, ползающаго по землј, представляющихъ какую-либо рыбу, которая въ водахъ ниже земли;',
        19: 'и дабы ты, взглянувъ на небо и увидјвъ солнце, луну и звјзды, все воинство небесное, не прельстился и не поклонился имъ и не служилъ имъ, которыя Господь, Богъ твой, раздјлилъ всјмъ народамъ подъ всјмъ небомъ.',
        20: 'А васъ взялъ Господь и вывелъ васъ изъ печи желјзной, изъ Египта, дабы вы были народомъ Его удјла, какъ это нынј видно.',
        21: 'Господь прогнјвался на меня за васъ и клялся, что я не перейду за Іорданъ и не войду въ ту добрую землю, которую Господь, Богъ твой, даетъ тебј въ удјлъ.',
        22: 'Я умру въ сей землј, не перешедши за Іорданъ, а вы перейдете и получите въ наслјдіе добрую оную землю.',
        23: 'Берегитесь, чтобы не забыть вамъ завјта Господа, Бога вашего, который Онъ поставилъ съ вами, и чтобы не дјлать себј кумировъ, изображающихъ что-либо, какъ повелјлъ тебј Господь, Богъ твой.',
        24: 'Поелику Господь, Богъ твой, есть огнь поядающій, Богъ ревнитель.',
        25: 'Если же родятся у тебя сыны и сыны у сыновъ, и долго живши на землј, вы развратитесь и сдјлаете изваяніе, изображающее что-либо, и сдјлаете зло сіе предъ очами Господа, Бога твоего, и раздражите Его:',
        26: 'то свидјтельствуюсь вамъ сегодня небомъ и землею, что пропадете, скоро пропадете съ земли, для наслјдованія которой вы переходите за Іорданъ; немного времени пробудете на ней, ибо истреблены будете.',
        27: 'И разсјетъ васъ Господь по народамъ, и останетесь въ маломъ числј между народами, къ которымъ отведетъ васъ Господь.',
        28: 'И будете тамъ служить богамъ, сдјланнымъ руками человјческими изъ дерева и камня, которые не видятъ и не слышагь, и не јдятъ и не обоняютъ.',
        29: 'Но когда ты взыщешь оттолј Господа, Бога твоего, то найдешь, если будешь искать Его всјмъ сердцемъ твоимъ и всею душею твоею.',
        30: 'Когда ты будешь въ скорби, и когда все сіе постигнетъ тебя въ послјдствіи времени; то обратишься ко Господу, Богу твоему, и послушаешь гласа Его.',
        31: 'Поелику Господь, Богъ твой, есть Богъ милосердый; Онъ не оставитъ тебя и не погубитъ тебя, и не забудетъ завјта съ отцами твоими, который Онъ клятвою утвердилъ имъ.',
        32: 'Ибо спроси у временъ прежнихъ, бывшихъ прежде тебя, съ того дня, въ который сотворилъ Богъ человјка на землј, и отъ края неба до края неба: бывало ли что нибудь такое, какъ сіе великое дјло, или слыхано ли подобное сему?',
        33: 'Слышалъ ли какой народъ гласъ Бога, говорящаго изъ среды огня, и остался живъ, какъ слышалъ ты?',
        34: 'Или покушался ли какой богъ пойти, взять себј народъ изъ среды другаго народа казнями, знаменіями и чудесами, и войною и рукою крјпкою, и мышцею высокою и великими ужасами, такъ какъ сдјлалъ для васъ Господь, Богъ вашъ, въ Египтј предъ глазами твоими?',
        35: 'Тебј дано видјть сіе, чтобы ты зналъ, что Господь - Онъ есть Богъ, и нјтъ еще кромј Его.',
        36: 'Съ неба далъ Онъ слышать тебј гласъ Свой, дабы научить тебя, и на землј показалъ тебј великій огнь Свой, и ты слышалъ слова Его изъ среды огня.',
        37: 'И поелику Онъ возлюбилъ отцевъ твоихъ и избралъ потомство ихъ послј нихъ, то и вывелъ тебя Самъ великою силою Своею изъ Египта,',
        38: 'чтобы прогнать отъ лица твоего народы, которые болје и сильнје тебя, и ввести тебя и дать тебј землю ихъ въ удјлъ, какъ это нынј видно.',
        39: 'Итакъ знай нынј и положи на сердце твое, что Господь - Онъ есть Богъ на небј вверху и на землј внизу, и нјтъ еще.',
        40: 'И храни постановленія Его и заповјди Его, которыя я заповјдаю тебј сегодня, чтобы хорошо было тебј и сынамъ твоимъ послј тебя, и чтобы ты продолжалъ дни на той землј, которую Господь, Богъ твой, даетъ тебј навсегда.',
        41: 'Тогда отдјлилъ Моисей три города по сю сторону Іордана на востокъ солнца,',
        42: 'чтобы убјгалъ туда убійца, который убьетъ ближняго своего безъ намјренія, не бывъ врагомъ ему ни вчера, ни третьяго дня, и чтобъ убјжавъ въ одинъ изъ сихъ городовъ, остался живъ:',
        43: 'Бецеръ въ пустынј, на равнинј въ колјнј Рувимовомъ, и Рамоѕъ вь Галаадј въ колјнј Гадовомъ, и Голанъ въ Васанј въ колјнј Манассіиномъ.',
        44: 'Вотъ законъ, который предложилъ Моисей сынамъ Израилевымъ;',
        45: 'вотъ откровенія, постановленія и уставы, которые изрекъ Моисей сынамъ Израилевымъ, по исшествіи ихъ изъ Египта,',
        46: 'за Іорданомъ на долинј противъ Беѕ-Пеора, въ землј Сигона, царя Аморрейскаго, жившаго въ Есевонј, котораго поразилъ Моисей съ сынами Израилевыми, по исшествіи ихъ изъ Египта;',
        47: 'и взяли въ наслјдіе землю его и землю Ога, царя Васанскаго, двухъ царей Аморрейскихъ, которая за Іорданомъ къ востоку солнца.',
        48: 'Начиная отъ Ароира, который лежитъ на берегу потока Арнона, до горы Сіона, она же Ермонъ,',
        49: 'и всю равнину по сю сторону Іордана къ востоку, до самаго моря равнины при подошвј Фазги.',
    },
    5: {
        1: 'И воззвалъ Моисей ко всему Израилю, и сказалъ имъ: слушай, Израиль, постановленія и законы, которые я изреку сегодня во уши ваши, и выучите ихъ и старайтесь исполнять ихъ.',
        2: 'Господь, Богъ нашъ, поставилъ съ нами завјтъ на Хоривј.',
        3: 'Не съ отцами нашими Господь поставилъ завјтъ сей, но съ нами, съ нами, которые здјсь сегодня всј живы.',
        4: 'Лицемъ къ лицу говорилъ Господь съ вами на горј изъ среды огня;',
        5: 'я же стоялъ между Господомъ и между вами въ то время, дабы пересказывать вамъ слово Господа, поелику вы боялись огня и не восходили на гору. Онъ сказалъ тогда:',
        6: 'Я, Господь, Богъ твой, Который вывелъ тебя изъ земли Египетской, изъ дома рабства.',
        7: 'Да не будетъ у тебя другихъ боговъ предъ лицемъ Моимъ.',
        8: 'Не дјлай себј кумира и никакого изображенія того, что на небј вверху, и что на землј внизу, и что въ водахъ ниже земли,',
        9: 'не поклоняйся имъ и не служи имъ: потому что Я Господь, Богъ твой, Богъ ревнитель, за вину отцевъ наказывающій дјтей до третьяго и четвертаго рода, ненавидящихъ Меня,',
        10: 'и творящій милость до тысячи родовъ любящимъ Меня и соблюдающимъ заповјди Мои.',
        11: 'Не произноси имени Господа, Бога твоего, напрасно: ибо не оставитъ Господь безъ наказанія того, кто произнесетъ имя Его напрасно.',
        12: 'Наблюдай день субботный, чтобы свято хранить его, какъ заповјдалъ тебј Господь, Богъ твой.',
        13: 'Шесть дней работай и дјлай всякія дјла твои;',
        14: 'а день седьмый суббота Господу, Богу твоему: не дјлай никакого дјла, ни ты, ни сынъ твой, ни дочь твоя, ни рабъ твой, ни раба твоя, ни волъ твой, ни оселъ твой, ни всякой скотъ твой, ни пришлецъ твой, который въ воротахъ твоихъ, чтобъ отдохнулъ рабъ твой, и раба твоя, какъ и ты.',
        15: 'И помни, что ты былъ рабомъ въ землј Египетской, но Господь, Богъ твой, вывелъ тебя оттуда рукою крјпкою и мышцею высокою, потому и повелјлъ тебј Господь, Богъ твой, учредить день субботный.',
        16: 'Почитай отца твоего и матерь твою, какъ повелјлъ тебј Господь, Богъ твой, чтобы продолжились дни твои, и чтобы хорошо тебј было на той землј, которую Господь, Богъ твой, даетъ тебј.',
        17: 'Не убивай.',
        18: 'Не прелюбодјйствуй.',
        19: 'Не крадь.',
        20: 'Не произноси ложнаго свидјтельства на ближняго твоего.',
        21: 'Не желай жены ближняго твоего и не желай дома ближняго твоего, ни поля его, ни раба его, ни рабы его, ни вола его, ни осла его, ни всего, что есть у ближняго твоего.',
        22: 'Слова сіи изрекъ Господь ко всему собранію вашему на горј изъ среды огня, облака и мрака, громогласно, и болје не говорилъ, и написалъ ихъ на двухъ каменныхъ скрижаляхъ и далъ ихъ мнј.',
        23: 'И когда вы услышали гласъ изъ среды мрака, и гора горјла огнемъ: то вы подошли ко мнј, всј начальники колјнъ вашихъ, и старјйшины ваши,',
        24: 'и сказали: вотъ, показалъ намъ Господь, Богъ нашъ, славу Свою и величіе Свое, и гласъ Его слышали мы изъ среды огня. Сегодня видјли мы, что Богъ говоритъ съ человјкомъ, и сей остается живъ:',
        25: 'но теперь, для чего умирать намъ? ибо великій огонь сей пожретъ насъ; если мы еще услышимъ гласъ Господа, Бога нашего, то умремъ.',
        26: 'Ибо есть ли какая плоть, которая бы слышала гласъ Бога живаго, говорящаго изъ среды огня, какъ мы, и осталась жива?',
        27: 'Приступи ты и слушай все, что скажетъ Господь, Богъ нашъ, и ты пересказывай намъ все, что будетъ говорить тебј Господь, Богъ нашъ, мы будемъ слушать и исполнять.',
        28: 'Господь услышалъ слова ваши, какъ вы разговаривали со мною, и сказалъ мнј Господь: слышалъ Я слова народа сего, которыя они говорили тебј; все, что ни говорили они, хорошо.',
        29: 'О! еслибы сердце ихъ было у нихъ таково, чтобы бояться Меня и соблюдать всј заповјди Мои во всј дни, дабы хорошо было имъ и сынамъ ихъ во вјкъ.',
        30: 'Поди, скажи имъ: возвратитесь въ шатры свои.',
        31: 'А ты здјсь останься со Мною, и Я изреку тебј всј заповјди и постановленія и законы, которымъ ты долженъ научить ихъ, чтобъ они такъ поступали на той землј, которую Я даю имъ въ наслјдіе.',
        32: 'Смотрите, поступайте такъ, какъ повелјлъ вамъ Господь, Богъ вашъ; не уклоняйтесь ни на право, ни на лјво.',
        33: 'Ходите по всему пути, по которому повелјлъ вамъ Господь, Богъ вашъ, дабы вы были живы, и хорошо было вамъ, и дабы вы продолжали дни на той землј, которую получите въ наслјдіе.',
    },
    6: {
        1: 'Сіи суть заповјди, постановленія и законы, которымъ повелјлъ Господь, Богъ вашъ, научить васъ, чтобы вы поступали такъ въ той землј, въ которую вы переходите, чтобы взять ее въ наслјдіе;',
        2: 'дабы ты боялся Господа, Бога твоего, и всј постановленія Его и заповјди Его, которыя заповјдаю тебј, соблюдалъ ты, и сынъ твой, и сынъ сына твоего во всј дни жизни твоей, дабы продолжились дни твои.',
        3: 'Итакъ слушай, Израиль, и старайся исполнить, чтобы тебј хорошо было, и чтобы вы весьма размножились; такъ какъ Господь, Богъ отцевъ твоихъ, говорилъ тебј, что Онъ даетъ тебј землю, гдј течетъ молоко и медъ.',
        4: 'Слушай, Израиль, Господь, Богъ нашъ, Господь единый.',
        5: 'И люби Господа, Бога твоего, всјмъ сердцемъ твоимъ и всею душею твоею и всјми силами твоими;',
        6: 'и да будутъ слова сіи, которыя я заповјдаю тебј сегодня, въ сердцј твоемъ,',
        7: 'и внушай ихъ дјтямъ, и говори объ нихъ, сидя въ домј твоемъ, и идучи дорогою, и лежа и стоя.',
        8: 'Навяжи ихъ въ знакъ на руку твою, и вмјсто повязки надъ глазами твоими,',
        9: 'и напиши ихъ на косякахъ дома твоего и на воротахъ твоихъ.',
        10: 'Когда же введетъ тебя Господь, Богъ твой, въ ту землю, которую Онъ клялся отцамъ твоимъ, Аврааму, Исааку и Іакову, дать тебј съ большими и хорошими городами, которыхъ ты не строилъ,',
        11: 'и съ домами, наполненными всякимъ добромъ, которыхъ ты не наполнялъ, и съ колодезями, высјченными изъ камня, которыхъ ты не высјкалъ, съ виноградниками и маслинами, которыхъ ты не садилъ, и будешь јсть и насыщаться:',
        12: 'тогда берегись, чтобы не забылъ ты Господа, Который вывелъ тебя изъ земли Египетской, изъ дома рабства.',
        13: 'Господа, Бога твоего, бойся, и Ему служи, и Его именемъ клянись.',
        14: 'Не послјдуйте другимъ богамъ, богамъ тјхъ народовъ, которые будутъ вокругъ васъ.',
        15: 'Ибо Господь, Богъ твой среди тебя, есть Богъ ревнитель, чтобы не воспламенился гнјвъ Господа, Бога твоего, на тебя, и не истребилъ Онъ тебя оть лица земли.',
        16: 'Не искушайте Господа, Бога вашего, какъ вы искушали Его въ Массј.',
        17: 'Твердо храните заповјди Господа, Бога вашего, и откровенія Его и постановленія Его, которыя Онъ заповјдалъ тебј.',
        18: 'И дјлай справедливое и доброе предъ очами Господа, дабы хорошо тебј было и дабы ты вошелъ и наслјдовалъ ту добрую землю, которую Господь съ клятвою објщалъ отцамъ твоимъ,',
        19: 'и чтобы Онъ прогналъ всјхъ враговъ твоихъ отъ лица твоего, какъ говорилъ Господь.',
        20: 'Если спроситъ у тебя сынъ твой въ послјдующее время, говоря: что значатъ сіи откровенія, постановленія и законы, которые заповјдалъ вамъ Господь, Богъ нашъ;',
        21: 'то скажи сыну твоему: рабами были мы у Фараона въ Египтј; и вывелъ насъ Господь изъ Египта рукою крјпкою.',
        22: 'И показалъ Господь знаменія и чудеса великія и казни надъ Египтомъ, надъ Фараономъ и надъ всјмъ домомъ его, предъ глазами нашими.',
        23: 'А насъ вывелъ оттуда, чтобы ввести насъ и дать намъ землю, которую клялся отцамъ нашимъ дать намъ.',
        24: 'И заповјдалъ намъ Господь исполнять всј постановленія сіи, чтобы мы боялись Господа, Бога нашего, дабы хорошо было намъ во всј дни, дабы сохранить нашу жизнь, какъ и теперь.',
        25: 'И праведность будетъ у насъ, когда мы будемъ стараться исполнять всј сіи заповјди предъ лицемъ Господа, Бога нашего, какъ повелјлъ Онъ намъ.',
    },
    7: {
        1: 'Когда введетъ тебя Господь, Богъ твой, въ ту землю, въ которую ты идешь, чтобы взять ее въ наслјдіе, и изгонитъ отъ лица твоего многочисленные народы, Хеттеевъ, Гергесеевъ, Аморреевъ, Хананеевъ, Ферезеевъ, Евеевъ и Іевусеевъ, семь народовъ, которые мнгочисленнје и сильнје тебя,',
        2: 'и предастъ ихъ тебј Господь, Богъ твой, и поразишь ихъ: тогда предай ихъ заклятію, не вступай съ ними въ союзъ и не щади ихъ.',
        3: 'И не вступай съ ними въ родство, дочери твоей не отдавай за сына его, и дочери его не бери за сына твоего;',
        4: 'ибо они отвратятъ сыновъ твоихъ отъ Меня, чтобы служить другимъ богамъ, и тогда воспламенится на васъ гнјвъ Господа, и Онъ скоро истребитъ тебя.',
        5: 'Но поступите съ ними такъ: жертвенники ихъ разрушьте, и столпы ихъ сокрушите, и рощи ихъ вырубите, и истуканы ихъ сожгите огнемъ.',
        6: 'Ибо ты народъ святый у Господа, Бога твоего; тебя избралъ Господь, Богъ твой, чтобы ты быль собственнымъ Его народомъ изъ всјхъ народовъ, которые на землј.',
        7: 'Не потому, чтобы вы были многочисленнје всјхъ народовъ, принялъ васъ Господь и избралъ васъ; ибо вы малочисленнје всјхъ народовъ.',
        8: 'Но потому, что любитъ васъ Господь, и для того, чтобъ сохранить клятву, которою Онъ клялся отцамъ вашимъ, вывелъ васъ Господь рукою крјпкою и освободилъ тебя изъ дома рабства, изъ руки Фараона, царя Египетскаго.',
        9: 'Знай, что Господь, Богъ твой, есть Богъ, Богъ вјрный, Который хранитъ завјтъ и милость къ любящимъ Его и сохраняющимъ заповјди Его, до тысящи родовъ.',
        10: 'А ненавидящимъ Его воздаетъ самимъ лично, погубляя ихъ, Онъ не медлитъ, ненавидящему Его самому лично воздастъ.',
        11: 'Итакъ соблюдай заповјди и постановленія и законы, которые сегодня заповјдую тебј исполнять.',
        12: 'Ибо если вы будете слушать законы сіи и хранить и исполнять ихъ, то и Господь, Богъ твой, будетъ хранить тебј завјтъ и милость, какъ Онъ клялся отцамъ твоимъ,',
        13: 'и возлюбитъ тебя, и благословитъ тебя, и размножитъ тебя, благословитъ плодъ чрева твоего и плодъ земли твоей, и хлјбъ твой, и вино твое, и елей твой, рождающееся отъ воловъ твоихъ, и стада овецъ твоихъ, на той землј, которую Онъ клялся отцамъ твоимъ дать тебј.',
        14: 'Благословенъ ты будешь паче всјхъ народовъ; не будетъ у тебя ни безплоднаго, ни безплодной, равно и въ скотј твоемъ.',
        15: 'И отдалитъ отъ тебя Господь всякую немощь, и никакихъ лютыхъ болјзней Египетскихъ, которыя ты знаешь, не наведетъ на тебя, но наведетъ ихъ на всјхъ ненавидящихъ тебя.',
        16: 'Истребляй всј тј народы, которые Господь, Богъ твой, даетъ тебј, да не пощадитъ ихъ око твое, и не служи богамъ ихъ: ибо это сјть для тебя.',
        17: 'Если скажешь въ сердцј твоемъ: народы сіи многочисленнје меня, какъ я могу изгнать ихъ?',
        18: 'Не бойся ихъ, вспомни то, что сдјлалъ Господь, Богъ твой, съ Фараономъ и всјмъ Египтомъ:',
        19: 'тј великія казни, которыя видјли глаза твои, знаменія, чудеса и руку крјпкую и мышцу высокую, коими вывелъ тебя Господь, Богъ твой. То же сдјлаетъ Господь, Богъ твой, со всјми народами, коихъ ты боишься.',
        20: 'И шершней нашлетъ Господь, Богъ твой, на нихъ, пока не погибнутъ оставшіеся и скрывшіеся отъ лица твоего.',
        21: 'Не страшись ихъ: ибо Господь, Богъ твой, среди тебя, Богъ великій и страшный.',
        22: 'Господь, Богъ твой, мало-по-малу будеть изгонять отъ тебя народы сіи; не можешь ты истребить ихъ скоро, чтобы не умножились во вредъ тебј полевые звјри.',
        23: 'Но предастъ ихъ тебј Господь, Богъ твой, и приведетъ ихъ въ великое смятеніе, такъ что они погибнутъ.',
        24: 'И предастъ царей ихъ въ руки твои, и ты истребишь имя ихъ изъ поднебесной: не устоить никто противъ тебя, пока не искоренишь ихъ.',
        25: 'Кумиры боговъ ихъ сожгите огнемъ; не пожелай взять себј серебра или золота, которое на нихъ, дабы это не было для тебя сјтію: ибо это мерзость для Господа, Бога твоего.',
        26: 'И не вноси мерзости въ домъ свой, дабы не подпасть заклятію, какъ она. Отвращайся сего и гнушайся сего; ибо это заклатое.',
    },
    8: {
        1: 'Всј заповјди, которыя я заповјдаю вамъ сегодня, старайтесь исполнять, дабы вы были живы и размножились, и пошли и наслјдовали ту землю, которую съ клятвою објщалъ Господь отцамъ вашимъ.',
        2: 'И помни весь путь, которымъ велъ тебя Господь, Богъ твой, по пустынј, вотъ уже сорокъ лјтъ, дабы смирить тебя, чтобы испытать тебя и узнать, что въ сердцј твоемъ, будешь ли хранить заповјди Его, или нјтъ.',
        3: 'Онъ смирялъ тебя, томилъ тебя голодомъ и питалъ тебя манною, которой не зналъ ты и не знали отцы твои, дабы показать тебј, что не однимъ хлјбомъ живетъ человјкъ, но всјмъ исходящимъ изъ устъ Господа живетъ человјкъ.',
        4: 'Одежда твоя не ветшала на тебј и нога твоя не пухла вотъ уже сорокъ лјтъ.',
        5: 'най въ сердцј твоемъ, что Господь, Богъ твой, учитъ тебя, какъ человјкъ учитъ сына своего.',
        6: 'Итакъ храни заповјди Господа, Бога твоего, ходя путями Его и боясь Его.',
        7: 'Ибо Господь, Богъ твой, ведетъ тебя въ землю добрую, въ землю, гдј потоки водъ, источники и бездны выходятъ изъ долинъ и горъ,',
        8: 'въ землю, гдј пшеница, ячмень, виноградныя лозы, смоковницы и гранатовыя деревъя, въ землю, гдј масличныя деревья съ елеемъ, и медъ, -',
        9: 'въ землю, въ которой безъ скудости будешь јсть хлјбъ, и ни въ чемъ не будешь имјть недостатка, въ землю, въ которой - камни, желјзо, и изъ горъ которой будешь высјкать мјдь.',
        10: 'И когда будешь јсть и насытишься: тогда благослови Господа, Бога твоего, за добрую землю, которую онъ далъ тебј.',
        11: 'Берегись, чтобъ ты не забылъГоспода, Бога твоего, не соблюдая заповјдей Его и законовъ Его, и постановленій Его, которыя сегодня заповјдаю тебј.',
        12: 'Когда будешь јсть и насытишься, и построишь хорошіе домы, и будешь жить въ нихъ;',
        13: 'и когда будетъ у тебя много крупнаго и мелкаго скота, и будетъ у тебя много серебра и золота, и всего у тебя будетъ много:',
        14: 'то смотри, чтобъ не надмилось сердце твое и не забылъ ты Господа, Бога твоего, Который вывелъ тебя изъ земли Египетской, изъ дома рабства,',
        15: 'Который провелъ тебя по пустынј великой и страшной, гдј змји, василиски, скорпіоны и земля сухая, на которой нјтъ воды, Который источилъ для тебя воды изъ скалы гранитной,',
        16: 'питалъ тебя въ пустынј манною, которой не знали отцы твои, дабы смирить тебя и испытать тебя, чтобы въ послјдствіи сдјлать тебј добро,',
        17: 'и чтобы ты не сказалъ въ сердцј твоемъ: моя сила и крјпостъ руки моей пріобрјли мнј богатство сіе,',
        18: 'но чтобы помнилъ Господа, Бога твоего, что Онъ далъ тебј силу пріобрјсть богатство, дабы исполнить завјтъ Свой, который Онъ клятвою утвердилъ отцамъ твоимъ, какъ теперь видишъ.',
        19: 'Если же ты забудешь Господа, Бога твоего, и пойдешь вслјдъ боговъ другихъ, и будешь служить имъ и покланяться имъ: то свидјтедьствуюсь вами сегодня, что вы погибнете.',
        20: 'Какъ прочіе народы, которыхъ Господь истребляетъ отъ лица вашего, такъ погибнете и вы за то, что не послушаете гласа Господа, Бога вашего.',
    },
    9: {
        1: 'Слушай, Израиль? ты теперь идешь за Іорданъ, чтобъ пойдти, взять въ наслјдіе народы, которые болје и сильнје тебя, города большіе съ укрјпленіями, возвышающимися до небесъ,',
        2: 'народъ многочисленный и великорослый, сыновъ Энаковыхъ, о которыхъ ты знаешь и слышалъ: "кто устоитъ противъ сыновъ Энаковыхъ?"',
        3: 'Знай нынј, что Господь, Богъ твой, пойдетъ предъ тобою, какъ огнь поядающій; Онъ будетъ истреблять ихъ, и Онъ низложитъ ихъ, и смиритъ ихъ предъ тобою, и изгонишь ихъ и погубишь ихъ скоро, какъ говорилъ тебј Господь.',
        4: 'Когда будетъ изгонять ихъ Господь, Богъ твой, отъ лица твоего, тогда не скажи въ сердцј своемъ: за праведность мою привелъ меня Господь, чтобъ наслјдовать землю сію, и за нечестіе народовъ сихъ Господь изгоняетъ ихъ отъ лица твоего.',
        5: 'Не за праведность твою и не за правоту сердца твоего ты идешь наслјдовать землю ихъ, но за нечестіе народовъ сихъ Господь, Богъ твой, изгоняетъ ихъ отъ лица твоего, и дабы исполнить слово, которое съ клятвою далъ Господь отцамъ твоимъ Аврааму, Исааку и Іакову.',
        6: 'Посему знай, что не за праведность твою Господь, Богъ твой, даетъ тебј наслјдовать сію добрую землю: ибо ты народъ жестоковыйный.',
        7: 'Вспомни, не забудь, сколько ты раздражалъ Господа, Бога твоего, въ пустынј: съ самаго того дня, какъ вышелъ ты изъ земли Египетской и до самаго пришествія вашего на мјсто сіе вы были упорны противъ Господа.',
        8: 'И при Хоривј вы раздражили Господа, и прогнјвался на васъ Господь, такъ что хотјлъ истребить васъ,',
        9: 'когда я взошелъ на гору, чтобы взять скрижали каменныя, скрижали завјта, который поставилъ Господь съ вами, и пробылъ на горј сорокъ дней и сорокъ ночей, хлјба не јлъ и воды не пилъ,',
        10: 'и далъ мнј Господь двј скрижали каменныя, написанныя перстомъ Божіимъ, а на нихъ всј слова, которыя изрекъ вамъ Господь на горј изъ среды огня въ день собранія.',
        11: 'По окончаніи же сорока дней и сорока ночей, далъ мнј Господь двј скрижали каменныя, скрижали завјта,',
        12: 'и сказалъ мнј Господь: встань, поди скорје отсюда, ибо развратился народъ твой, который ты вывелъ изъ Египта; скоро уклонились они отъ пути, который Я заповјдалъ имъ, они сдјлали себј литой истуканъ.',
        13: 'И сказалъ мнј Господь: вижу Я народъ сей, что это народъ жестоковыйный.',
        14: 'Не удерживай Меня, истреблю Я ихъ и изглажу имя ихъ изъ поднебесной; а отъ тебя произведу народъ, который будетъ сильнје и многочисленнје его.',
        15: 'Я обратился и пошелъ съ горы, гора же горјла огнемъ, двј скрижали завјта были въ објихъ рукахъ моихъ,',
        16: 'и вижу, и вотъ вы согрјшили противъ Господа, Бога вашего, сдјлали себј литаго тельца, скоро уклонились отъ пути, котораго держаться заповјдалъ вамъ Господь.',
        17: 'Тогда взялъ я обј скрижали, и бросилъ ихъ изъ објихъ рукъ своихъ и разбилъ ихъ предъ глазами вашими.',
        18: 'И повергшись предъ Господомъ, я умолялъ, какъ прежде, сорокъ дней и сорокъ ночей, хлјба не јлъ и воды не пилъ, за всј грјхи ваши, коими вы согрјшили, сдјлавъ зло въ очахъ Господа и раздраживъ Его.',
        19: 'Ибо я страшился гнјва и ярости, коими Господь прогнјвался на васъ, хотјвъ погубить васъ; и послушалъ меня Господь и на сей разъ.',
        20: 'И на Аарона весьма прогнјвался Господь, и хотјлъ погубить его; но я молился и за Аарона въ то время.',
        21: 'Грјхъ же вашъ, который вы сдјлали, тельца я взялъ, сожегъ его въ огнј, разбилъ его и всего истеръ до того, что онъ сталъ мелокъ, какъ пыль, и бросилъ пыль сію въ потокъ, текущій съ горы.',
        22: 'Кромј сего вы раздражили Господа въ Таверј, въ Массј и въ Киброт-таавј;',
        23: 'также, когда посылалъ васъ Господь изъ Кадесъ-Варни, говоря: подите, возьмите въ наслјдіе землю, которую Я даю вамъ; но вы воспротивились повелјнію Господа, Бога вашего, и не вјровали Ему и не послушали гласа Его.',
        24: 'Вы были непокорны Господу съ того самаго дня, какъ я сталъ знать васъ.',
        25: 'И повергшись предъ Господомъ, умолялъ я сорокъ дней и сорокъ ночей, въ которые я повергшись умолялъ: ибо Господь вознамјрился погубить васъ.',
        26: 'И молился я Господу, и сказалъ: Господи, Господи, не погубляй народа Твоего и наслјдія Твоего, который Ты избавилъ величіемъ Твоимъ, который вывелъ Ты изъ Египта рукою сильною.',
        27: 'Вспомни рабовъ Твоихъ Авраама, Исаака и Іакова; не обращай взоровъ на ожесточеніе народа сего, и на нечестіе его, и на грјхъ его,',
        28: 'дабы въ той землј, откуда Ты вывелъ насъ, не сказали: поелику Господь не могъ ввести ихъ въ землю, которую објщалъ имъ, и поелику ненавидитъ ихъ, то и вывелъ Онъ ихъ, чтобъ умертвить ихъ въ пустынј.',
        29: 'А они Твой народъ и Твое наслјдіе, который Ты вывелъ силою Твоею великою и мышцею Твоею высокою.',
    },
    10: {
        1: 'Въ то время сказалъ мнј Господь: вытеши себј двј скрижали каменныя, подобныя первымъ, и взойди ко Мнј на гору и сдјлай себј деревянный ковчегъ.',
        2: 'И Я напишу на скрижаляхъ тј слова, которыя были на прежнихъ скрижаляхъ, которыя ты разбилъ; и положи ихъ въ ковчегъ.',
        3: 'И сдјлалъ я ковчегъ изъ дерева акаціи и вытесалъ двј каменныя скрижали, какъ прежнія, и пошелъ на гору, и двј сіи скрижали были въ рукј моей.',
        4: 'И написалъ Онъ на скрижаляхъ, какъ написано было прежде, тј десять словъ, которыя изрекъ вамъ Господь на горј изъ среды огня въ день собранія, и отдалъ ихъ Господь мнј.',
        5: 'Я пошелъ назадъ, и сошелъ съ горы и положилъ скрижали въ ковчегь, который я сдјлалъ, чтобъ онј тамъ были, какъ повелјлъ мнј Господь.',
        6: 'Сыны Израилевы отправились изъ Беероѕъ-Бне-Іакана въ Мозеръ; тамъ умеръ Ааронъ и погребенъ тамъ, и священство принялъ вмјсто его сынъ его Елеазаръ.',
        7: 'Оттуда отправились въ Гудгодъ, изъ Гудгода въ Іотаваѕу, землю, иаобилующую потоками водъ.',
        8: 'Въ то время отдјлилъ Господь колјно Левіино, чтобы носить ковчегъ завјта Господня, предстоять предъ Господомъ, служить Ему и благословлять именемъ Его, какъ это продолжается до сего дня.',
        9: 'Потому нјтъ левиту части и удјла съ братьями его; Самъ Господъ есть удјлъ его, какъ говорилъ ему Господь, Богъ твой.',
        10: 'Такимъ образомъ пробылъ я на горј, какъ и въ прежнее время, сорокъ дней и сорокъ иочей; и послушалъ меня Господь и на сей разъ; не восхотјлъ Господь погубить тебя.',
        11: 'И сказалъ мнј Господь: встань, поди въ путь предъ народомъ; пусть они пойдутъ и наслјдуютъ землю, которую Я клялся отцамъ ихъ дать имъ.',
        12: 'Итакъ, Израиль, чего требуетъ отъ тебя Господь, Богъ твой? Того только, чтобы ты боялся Господа, Бога твоего, ходилъ всјми путями его, и любилъ Его, служилъ Господу, Богу твоему, отъ всего сердца твоего и отъ всей души твоей,',
        13: 'чтобъ ты соблюдалъ заповјди Господа и постановленія Его, которыя сегодня заповјдаю тебј, чтобъ тебј было хорошо.',
        14: 'Се, у Господа, Бога твоего, небо и небеса небесъ, земля и все, что на ней;',
        15: 'но только отцевъ твоихъ принялъ Господь и возлюбилъ ихъ, и избралъ васъ, сјмя ихъ послј нихъ, изъ всјхъ народовъ, какъ нынј видишь.',
        16: 'Итакъ обрјжьте крайнюю плоть сердца вашего и не будьте впередъ жестоковыйны.',
        17: 'Ибо Господь, Богъ вашъ, есть Богъ боговъ, и Владыка владыкъ, Богъ великій, сильный и страшный, Который не смотритъ на лица и не беретъ даровъ,',
        18: 'Который даетъ судъ сиротј и вдовј, и любитъ пришельца, даетъ ему хлјбъ и одежду.',
        19: 'Любите пришельца; ибо сами вы были пришельцами въ землј Египетской.',
        20: 'Господа, Бога твоего, бойся, Ему служи и къ нему прилјпись и Его именемъ клянись.',
        21: 'Онъ хвала твоя и Онъ Богъ твой, Который сдјлалъ съ тобою оныя великія и страшныя дјла, какія видјли глаза твои.',
        22: 'Въ семидесяти душахъ пришли отцы твои въ Египетъ, а нынј Господь, Богъ твой, сдјлалъ тебя многочисленнымъ, какъ звјзды небесныя.',
    },
    11: {
        1: 'Итакъ люби Господа, Бога твоего, и храни, что повелјно Имъ хранить, и постановленія Его, и заковы Его, и заповјди Его во всј дни.',
        2: 'Вы знаете нынј (ибо я говорю не съ сынами вашими, которые не знаютъ и не видјли) наказанія Господа, Бога вашего, Его величіе, Его крјпкую руку и высокую мышцу Его,',
        3: 'знаменія Его и дјла Его, которыя Онъ сдјлялъ среди Египта съ Фараономъ, царемъ Египетскимъ и со всею землею его,',
        4: 'и что Онъ сдјлалъ съ воинствомъ Египетскимъ, конями его и колесницами его, которыхъ Онъ потопилъ водами Чермнаго моря, когда они гнались за вами, и погубилъ ихъ Господь до сего дня;',
        5: 'и что Онъ дјлалъ для васъ въ пустынј, пока вы дошли до мјста сего,',
        6: 'и что Онъ сдјлалъ съ Даѕаномъ и Авирамомъ сынами Еліава, сына Рувимова, когда земля разверзла уста свои и среди всего Израиля поглотила ихъ, и семейства ихъ, и шатры ихъ, и все имущество ихъ, которое было у нихъ',
        7: 'Ибо глаза ваши видјли всј великія дјла Господа, которыя Онъ сдјлалъ.',
        8: 'Храните всј заповјди, которыя я заповјдаю вамъ сегодня, дабы вы укрјпились, и пошли и взяли въ наслјдіе ту землю, въ которую вы переходите, чтобъ наслјдовать ее;',
        9: 'и дабы вы жили много времени на той землј, которую клялся Господь отцамъ вашимъ дать имъ и сјмени ихъ, на землј, гдј течетъ молоко и медъ.',
        10: 'Ибо земля, которую ты идешь взять въ наслјдіе, не такова, какъ земля Египетская, изъ которой вы вышли, гдј ты; посјявъ сјмя свое, напаялъ посредствомъ машинъ, какъ овощный садъ.',
        11: 'Но земля, въ которую вы переходите, чтобъ наслјдовать ее, есть земля съ горами и долинами, и отъ дождя небеснаго напояется водою,',
        12: 'земля, о которой Господь, Богъ твой, печется; очи Господа, Бога твоего, непрестанно на ней, отъ начала года и до конца года.',
        13: 'Если вы будете слушать заповјди Мои, которыя заповјдаю Я вамъ сегодня, будете любить Господа, Бога вашего, и служить Ему отъ всего сердца вашего и отъ всей души вашей:',
        14: 'то дамъ землј вашей дождь въ свое время, ранній и поздній, и ты соберешь хлјбъ свой и вино свое и елей свой;',
        15: 'и дамъ траву на полј твоемъ скоту твоему, ты будешь јсть и насытишься.',
        16: 'Берегитесь, чтобы не обольстилось сердце ваше, и вы не уклонились, и не стали служить другимъ богамъ и не поклонились имъ;',
        17: 'иначе воспламенится гнјвъ Господа на васъ и заключитъ Онъ небо, не будетъ дождя и земля не принесетъ произведеній своихъ: и вы скоро потеряете сію добрую землю, которую Господь даетъ вамъ.',
        18: 'Итакъ положите сіи слова Мои въ сердце ваше и въ душу вашу, и навяжите ихъ въ знакъ на руку свою, и да будутъ они вмјсто повязки надъ глазами вашими.',
        19: 'И учите имъ сыновей своихъ, говоря о нихъ, когда ты сидишь въ домј своемъ, и когда идешь дорогою, и когда лежишь и когда стоишь.',
        20: 'И напиши ихъ на косякахъ въ домј твоемъ и на воротахъ твоихъ,',
        21: 'дабы столь же много было дней вашихъ и дней сыновъ вашихъ на той землј, которую Господь клялся дать отцамъ вашимъ, сколько дней небо стоитъ надъ землею.',
        22: 'Ибо если вы будете соблюдать всј заповјди сіи, которыя заповјдаю вамъ исполнять, будете любить Господа, Бога вашего, ходить всјми путями Его и къ Нему прилјпляться',
        23: 'то изгонитъ Господь всј народы оные отъ лица вашего, и вы овладјете народами, которые болје и сильнје васъ.',
        24: 'Всякое мјсто, на которое ступитъ нога ваша, будетъ ваше; отъ пустыни и Ливана, отъ рјки, рјки Евфрата даже до моря западнаго будутъ предјлы ваши.',
        25: 'Никто не устоитъ противу васъ: Господъ, Богъ вашъ, наведетъ страхъ вашъ и трепетъ вашъ на всякую землю, на которую вы ступите, какъ говорилъ вамъ.',
        26: 'Се, я предлагаю вамъ сегодня благословеніе и проклятіе:',
        27: 'благословеніе, если послушаете заповјдей Господа, Бога вашего, которыя я заповјдаю вамъ сегодня,',
        28: 'а проклятіе, если не послушаете заповјдей Господа, Бога вашего, и уклонитесь отъ пути, который я вамъ сегодня заповјдаю, и пойдете вслјдъ боговъ иныхъ, которыхъ вы незнали.',
        29: 'Когда введетъ тебя Господь, Богъ твой, въ ту землю, въ которую ты идешь, чтобы взять ее въ наслјдіе: тогда произнеси благословеніе на горј Гаризимј, а проклятіе на горј Гевалј.',
        30: '(Вотъ онј за Іорданомъ, за дорогою, которая къ западу солнца, въ землј Хананеевъ, живущихъ на равнинј, противъ Галгала, близъ дубравы Море).',
        31: 'Ибо вы переходите за Іорданъ, чтобы пойдти, взять въ наслјдіе землю, которую Господь, Богъ вашъ, даетъ вамъ, и возьмете ее въ наслјдіе и будете жить на ней.',
        32: 'Тогда старайтесь соблюсти всј постановленія и законы, которые предлагаю я вамъ сегодня.',
    },
    12: {
        1: 'Сіи сутъ постановленія и законы, которые вы должны стараться исполнять въ той землј, которую Господь, Богъ отцевъ твоихъ, даетъ тебј въ наслјдіе во всј дни, которые вы будете жить на той землј:',
        2: 'истребите всј мјста, гдј народы, которыми вы овладјете, служили богамъ своимъ, на высокихъ горахъ, и на холмахъ, и подъ всякимъ зеленјющимъ деревомъ.',
        3: 'Разрушьте жертвенники ихъ, сокрушите столпы ихъ, сожгите огнемъ рощи ихъ, разбейте истуканы боговъ ихъ, истребите имя ихъ отъ мјста того.',
        4: 'Не то должны вы дјлать для Господа, Бога вашего.',
        5: 'Но на мјстј, какое изберетъ Господь, Богъ вашъ, изъ всјхъ колјнъ вашихъ, чтобы положить имя Свое тамъ, и жить на немъ, тамъ ищите Его и туда приходите,',
        6: 'и туда приносите всесожженія ваши, и жертвы ваши, и десятины ваши, и возношеніе рукъ вашихъ, и објты ваши, и приношенія усердія вашего, и первенцевъ крупнаго скота вашего, и мелкаго скота вашего,',
        7: 'и јшьте тамъ предъ Господомъ, Богомъ вашимъ, и веселитесъ, вы и семейства ваши, о всемъ, что проходило чрезъ руки ваши, чјмъ благословилъ тебя Господь, Богъ твой.',
        8: 'Тамъ вы не должны дјлать всего того, что мы теперь здјсь дјлаемъ; ибо дјлаемъ все, что кому кажется правильнымъ,',
        9: 'Ибо вы нынј еще не вступили въ мјсто покоя и въ удјлъ, который Господь, Богъ твой, даетъ тебј.',
        10: 'Но когда перейдете за Іорданъ и поселитесь на той землј, которую Господь, Богъ вашъ, даетъ вамъ въ удјлъ, и когда Онъ успокоитъ васъ отъ всјхъ враговъ вашихъ, окружающихъ васъ, и будете жить безопасно:',
        11: 'тогда, какое мјсто изберетъ Господь, Богъ вашъ, чтобы обитать имени Его тамъ, туда приносите все, что я заповјдаю вамъ: всесожженія ваши и жертвы ваши, десятины ваши и возношеніе рукъ вашихъ, и все избранное по објтамъ вашимъ, что вы објщали Господу.',
        12: 'И веселитесь предъ Господомъ, Богомъ вашимъ, вы и сыны ваши, и дочери ваши, и рабы ваши и рабыни ваши, и левитъ, который въ жилищахъ вашихъ, ибо нјтъ ему части и удјла съ вами.',
        13: 'Берегись приносить всесожженія твои на всякомъ мјстј, которое ты увидишь;',
        14: 'но на томъ только мјстј, которое изберетъ Господь въ одномъ изъ колјнъ твоихъ, приноси всесожженія твои, и дјлай все, что я заповјдую тебј.',
        15: 'Впрочемъ, когда только пожелаетъ душа твоя, можешь закалать и јсть мясо, по благословенію Господа, Бога твоего, которое Онъ далъ тебј, во всјхъ жилищахъ твоихъ, нечистый и чистый могутъ јсть сіе, какъ серну и какъ оленя.',
        16: 'Только крови не јшьте, на землю выливайте ее, какъ воду.',
        17: 'Не можно тебј јсть въ жилищахъ твоихъ десятины хлјба твоего, и вина твоего, и елея твоего, и первенцевъ крупнаго скота твоего и мелкаго скота твоего, и всјхъ објтовъ твоихъ, которые ты објщалъ, и приносимаго по усердію твоему и возносимаго руками твоими.',
        18: 'Но јшь сіе предъ Господомъ, Богомъ твоимъ, на томъ мјстј, которое изберетъ Господь, Богъ твой, ты, и сынъ твой, и дочь твоя, и рабъ твой и раба твоя, и левитъ, который въ жилищахъ твоихъ, и веселись предъ Господомъ, Богомъ твоимъ, о всемъ, что проходило чрезъ руки твои.',
        19: 'Смотри, не оставляй левита во всј дни на землј твоей.',
        20: 'Когда распространитъ Господь, Богъ твой, предјлы твои, какъ Онъ говорилъ тебј, и ты скажешь: "појмъ я мяса," потому что душа твоя пожелаетъ јсть мяса: тогда, по желанію души твоей, јшь мясо.',
        21: 'Если-далеко будетъ отъ тебя то мјсто, которое изберетъ Господь, Богъ твой, чтобы положить имя Свое тамъ: то закалай изъ крупнаго и мелкаго скота твоего, который далъ тебј Господь, какъ я повелјлъ тебј, и јшь во вратахъ твоихъ, по желанію души твоей.',
        22: 'Впрочемъ јшь ихъ такъ, какъ јдятъ серну и оленя, нечистый какъ и чистый могутъ јсть сіе.',
        23: 'Только крјпко наблюдай, чтобы не јсть крови, потому что кровь есть душа; не јшь души вмјстј съ мясомъ.',
        24: 'Не јшь ея, выливай ее на землю, какъ воду.',
        25: 'Не јшь ея, дабы херошо было тебј и дјтямъ твоимъ послј тебя, когда будешь дјлать справедливое предъ очами Господа.',
        26: 'Только святыни твои, какія будутъ у тебя, и објты твои приноси, и приходи на то мјсто, которое изберетъ Господь,',
        27: 'и совершай всесожженія твои, мясо и кровь полагая на жертвенникъ Господа, Бога твоего; но кровь другихъ жертвъ твоихъ должна быть проливаема у жертвенника Господа, Бога твоего, а мясо јшь.',
        28: 'Со вниманіемъ слушай всј слова сіи, которыя заповјдаю тебј, дабы хорошо было тебј и дјтямъ твоимъ послј тебя во вјкъ, когда ты будешь дјлать доброе и справедливое предъ очами Господа, Бога твоего.',
        29: 'Когда Господь, Богъ твой, истребитъ отъ лица твоего народы, которыхъ ты идешь взять въ наслјдіе, и ты возьмешь ихъ въ наслјдіе и поселишься въ землј ихъ:',
        30: 'тогда берегись, чтобы ты не попалъ въ сјть, послјдуя имъ; когда они будутъ истреблены отъ лица твоего, не ищи боговъ ихъ, говоря: какъ почитали боговъ своихъ народы сіи, буду и я дјлать также.',
        31: 'Не дјлай такъ Господу, Богу твоему, поелику все, чего гнушается Господь, что ненавидитъ Онъ, они дјлаютъ богамъ своимъ; они и сыновъ своихъ и дочерей своихъ сожигаютъ на огнј богамъ своимъ.',
        32: 'Все, что я заповјдаю вамъ, старайтесь исполнять, не прибавляй къ тому и не убавляй отъ того.',
    },
    13: {
        1: 'Если возстанеть среди тебя пророкъ, или сновидецъ и представитъ тебј знаменіе или чудо,',
        2: 'и сбудется то знаменіе или чудо, о которомъ онъ говорилъ тебј, и скажетъ притомъ: пойдемъ въ слјдъ боговъ другихъ, которыхъ ты незнаешь, и будемъ служить имъ:',
        3: 'то не слушай словъ пророка сего, или сновидца сего; ибо чрезъ сіе искушаетъ васъ Господъ, Богъ вашъ, чтобы узнать - любите ли вы Господа, Бога вашего, отъ всего сердца вашего и отъ всей души вашей.',
        4: 'Господу, Богу вашему, послјдуйте и Его бойтеся; Его заповјди храните, Его гласа слушайте, и Ему служите и къ Нему прилјпляйтесь.',
        5: 'А пророка того или сновидца того должно предать смерти за то, что онъ уговаривалъ отступить отъ Господа, Бога вашего, выведшаго васъ изъ земли Египетской, и избавившаго тебя изъ дома рабства, - дабы совратить тебя съ пути, по которому заповјдалъ тебј Господь, Богъ твой, идти; и такимъ образомъ истреби зло изъ среды себя.',
        6: 'Если будетъ убјждать тебя братъ твой, сынъ матери твоей, или сынъ твой, или дочь твоя, или жена твоя на ложј твоемъ, или другъ твой, который для тебя, какъ душа твоя, тайно говоря: пойдемъ и будемъ служить богамъ другимъ, коихъ незналъ ты и отцы твои,',
        7: 'богамъ тјхъ народовъ, которые вокругъ тебя, близкихъ къ тебј или отдаленныхъ отъ тебя, отъ одного края земли до другаго:',
        8: 'то не соглашайся съ нимъ и не слушай его; и да не пощадитъ его око твое, не жалјй его и не прикрывай его,',
        9: 'но убей его: твоя рука прежде всјхъ должна быть на немъ, чтобы убить его, а потомъ руки всего народа.',
        10: 'Побей его камнями до смерти; ибо онъ покушался отвратитъ тебя отъ Господа, Бога твоего, Который вывелъ тебя изъ земли Египетской, изъ дома рабства.',
        11: 'Весь Израиль услышитъ сіе и убоится, и не станутъ впредь дјлать среди тебя такого зла.',
        12: 'Если услышишь, что въ какомъ-либо изъ городовъ твоихъ, которые Господь, Богъ твой, даетъ тебј для жительства,',
        13: 'появились нечестивые люди изъ среды тебя и соблазнили жителей города ихъ, говоря: пойдемъ и будемъ служить богамъ другимъ, которыхъ вы не знали;',
        14: 'то ты разыщи, изслјдуй и хорошо выспроси, и если это точная правда, если сдјлана мерзость сія среди тебя:',
        15: 'то порази жителей того города остріемъ меча, предай заклятію его, и все, что въ немъ, и скотъ его порази остріемъ меча.',
        16: 'Всю же добычу его собери на средину площади его, и сожги огнемъ городъ и всю добычу его во всесожженіе Господу, Богу твоему, и да будетъ онъ вјчно въ развалинахъ, не должно его никогда вновь созидать.',
        17: 'Ничто изъ заклятаго да не прилипнетъ къ рукј твоей, дабы укротилъ Господь ярость гнјва Своего, далъ тебј милость и помиловалъ тебя, и размножилъ тебя, какъ клялся отцамъ твоимъ,',
        18: 'если будешь слушать гласа Господа, Бога твоего, соблюдая всј заповјди Его, которыя нынј заповјдаю тебј, дјлая справедливое предъ очами Господа, Бога твоего.',
    },
    14: {
        1: 'Вы сыны Господа, Бога вашего, не надрјзывайте тјла вашего и не выстригайте волосъ надъ глазами вашими, плача по умершемъ:',
        2: 'поелику ты народъ святый у Господа, Бога твоего, и тебя избралъ Господь, чтобъ ты былъ собственнымъ Его народомъ изъ всјхъ народовъ, которые на землј.',
        3: 'Не јшь ничего гнуснаго.',
        4: 'Вотъ скотъ, который вамъ можно јсть: коровы, овцы, козы,',
        5: 'олень, серна, и сайгакъ, и сайга, и пигаргъ, и ориксъ, и зубръ.',
        6: 'Всякой скотъ, у котораго раздвоены копыта и на објихъ копытахъ глубокой разрјзъ, и который скотъ жуетъ жвачку, тотъ јшьте.',
        7: 'Только сихъ не јшьте изъ жующихъ жвачку и имјющихъ раздвоенныя копыта съ глубокимъ разрјзомъ: верблюда, зайца и тушканчика; потому что хотя они жуютъ жвачку, но копыта у нихъ не раздвоены: нечисты они для васъ;',
        8: 'и свиньи, потому что копыта у ней раздвоены, но не жуетъ жвачки: нечиста она для васъ; не јшъте мяса ихъ и къ трупамъ ихъ не прикасайтесь.',
        9: 'Изъ всјхъ животныхъ, которыя въ водј, јшьте сіи: у которыхъ есть перья и чешуя, всј тј јшьте;',
        10: 'но всјхъ тјхъ, у которыхъ нјтъ перьевъ и чешуи, не јшьте: нечисто это для васъ.',
        11: 'Всякую пищу чистую јшьте.',
        12: 'Но сихъ не должно вамъ јсть изъ нихъ: орла, грифа и морскаго орла,',
        13: 'коршуна, сокола и кречета, съ породою ихъ,',
        14: 'и всякаго ворона съ породою его,',
        15: 'строуса, совы, чайки, и ястреба съ породою его,',
        16: 'филина, ибиса и лебедя,',
        17: 'пеликана, сипа и рыболова,',
        18: 'цапли, и зуя съ породою его, удода и нетопыря.',
        19: 'И всякое животное пресмыкающееся крылатое нечисто для васъ; не должно јсть его.',
        20: 'Всякую птицу чистую јшьте.',
        21: 'Не јшьте никакой мертвечины; пришельцу, который будетъ въ жилищахъ твоихъ, отдай ее, онъ пустъ јстъ ее, или продай иноземцу: ибо ты народъ святый у Господа, Бога твоего. Не вари козленка въ молокј матери его.',
        22: 'Отдјляй десятину отъ всего произведенія сјмянъ твоихъ, которое приходитъ съ поля каждогодно.',
        23: 'И јшь предъ Господомъ, Богомъ твоимъ, на томъ мјстј, которое Онъ изберетъ, чтобъ обитать имени Его тамъ, десятину хлјба твоего, вина твоего и елея твоего, и первенцевъ крупнаго скота твоего и мелкаго скота твоего, дабы ты научился бояться Господа, Бога твоего, во всј дни.',
        24: 'Если же длинна будетъ для тебя дорога, такъ что ты не можешь нести сего, потому что далеко отъ тебя то мјсто, которое изберетъ Господь, Богъ твой, чтобъ положить тамъ имя Свое: то, когда благословилъ тебя Господь, Богъ твой,',
        25: 'продай это за серебро, и возьми серебро въ руку твою, и приходи на то мјсто, которое изберетъ Господь, Богъ твой,',
        26: 'и покупай на серебро сіе всего, чего пожелаетъ душа твоя, воловъ, овецъ, вина, напитковъ и всего, чего потребуетъ отъ тебя душа твоя, и јшь тамъ предъ Господомъ, Богомъ твоимъ, и веселисъ ты и семейство твое,',
        27: 'и левита, который въ жилищахъ твоихъ, не оставь; поелику нјтъ ему части и удјла съ тобою.',
        28: 'По прошествіи же трехъ лјтъ отдјляй всј десятины произведеній твоихъ въ тотъ годъ, и клади сіе въ жилищахъ твоихъ;',
        29: 'и пусть придетъ левитъ, поелику нјтъ ему части и удјла съ тобою, и пришлецъ и сирота, и вдова, которые находятся въ жилищахъ твоихъ, и пусть јдятъ и насыщаются; дабы благословилъ тебя Господь, Богъ твой, во всякомъ дјлј рукъ твоихъ, которое ты будешь дјлать.',
    },
    15: {
        1: 'По наступленіи седьмаго года дјлай прощеніе.',
        2: 'Прощеніе же состоитъ въ томъ, чтобъ всякій заимодавецъ, который далъ взаймы ближнему своему, простилъ долгъ и не взыскивалъ съ ближняго своего и съ брата своего, когда провозглашено будетъ прощеніе ради Господа.',
        3: 'Съ иноземца взыскивай, а что будетъ твое у брата твоего, прости.',
        4: 'Развј только не будетъ у тебя нищаго; ибо благословитъ тебя Господь на той землј, которую Господь, Богъ твой, даетъ тебј въ удјлъ, чтобъ ты взялъ ее въ наслјдіе.',
        5: 'Если только будешь слушать гласа Господа, Бога твоего, и стараться исполнять всј заповјди сіи, которыя я сегодня заповјдаю тебј:',
        6: 'то Господь, Богъ твой, благословитъ тебя, какъ Онъ говорилъ тебј, и ты будешь давать взаймы многимъ народамъ, а самъ не будешь брать взаймы, и господствовать будешь надъ многими народами, а они надъ тобою не будутъ господствовать.',
        7: 'Если же будетъ у тебя нищій кто-либо изъ братьевъ твоихъ, въ одномъ изъ жилищъ твоихъ, на землј твоей, которую Господь, Богъ твой, даетъ тебј: то не ожесточи сердца твоего и не сожми руки твоей предъ нищимъ братомъ твоимъ;',
        8: 'но открой ему руку свою и дай ему взаймы, смотря по его нуждј, въ чемъ онъ нуждается.',
        9: 'Берегись, чтобъ не вошла въ сердце твое беззаконная мысль: приближается седьмой годъ, годъ прощенія; и чтобъ отъ того око твое не сдјлалось немилостиво къ нищему брату твоему, и ты не отказалъ ему; ибо онъ возопіетъ на тебя къ Господу, и будетъ на тебј грјхъ.',
        10: 'Дай ему, и когда будешь давать ему, не должно скорбјть сердце твое; ибо за сіе благословитъ тебя Господь, Богъ твой, во всјхъ дјлахъ твонхъ и во всемъ, что будетъ проходить чрезъ твои руки.',
        11: 'Поелику нищіе всегда будутъ среди земли; потому я и повелјваю тебј, говоря: отверзай руку твою брату твоему, бјдному твоему и нищему твоему на землј твоей.',
        12: 'Если продастся тебј братъ твой, Еврей или Евреянка: то шесть лјтъ онъ долженъ служить тебј, а въ седьмой годъ отпусти его отъ себя на свободу.',
        13: 'Когда же будешь отпускать его отъ себя на свободу, не отпусти его съ пустыми руками;',
        14: 'но награди его чјмъ-нибудь изъ стадъ твоихъ, съ гумна твоего и изъ точила твоего; дай ему, чјмъ благословилъ тебя Господь, Богъ твой.',
        15: 'Вспомни, что ты былъ рабомъ въ землј Египетской, и избавилъ тебя Господь, Богъ твой; потому я сегодня и заповјдаю тебј сіе.',
        16: 'Если же онъ скажетъ тебј: не пойду я отъ тебя, потому что я люблю тебя и домъ твой, потому что хорошо ему у тебя:',
        17: 'то возьми шило, и приколи ухо его къ двери, и будетъ онъ слугою твоимъ навјкъ. Такимъ образомъ поступи и съ служанкою твоею.',
        18: 'Не считай это для себя тяжкимъ, что ты долженъ отпустить его отъ себя на свободу; ибо онъ въ продолженіи шести лјтъ заработалъ тебј вдвое противъ платы наемника, и благословитъ тебя Господь, Богъ твой, во всемъ, что ни будешь дјлать.',
        19: 'Все первородное мужескаго пола, что родится отъ крупнаго скота твоего, и отъ мелкаго скота твоего, посвящай Господу, Богу твоему; не работай на первородномъ волј твоемъ и не стриги первороднаго изъ овецъ твоихъ.',
        20: 'Предъ Господомъ, Богомъ твоимъ, каждогодно съјдай это ты и семейство твое, на мјстј, которое изберетъ Господь.',
        21: 'Если же будетъ на немъ порокъ, если оно будетъ хромо, или слјпо, или по другому какому пороку негодно: то не приноси его въ жертву Господу, Богу твоему.',
        22: 'Въ жилищахъ твоихъ јшь его; нечистый какъ и чистый могутъ јсть, какъ серну и какъ оленя.',
        23: 'Только крови его не јшь, на землю выливай ее, какъ воду.',
    },
    16: {
        1: 'Наблюдай мјсяцъ Авивъ, и совершай Пасху Господу, Богу твоему, потому что въ мјсяцј Авивј вывелъ тебя Господь, Богъ твой, изъ Египта ночью.',
        2: 'Заколай Пасху Господу, Богу твоему, изъ мелкаго и крупнаго скота, на мјстј, которое изберетъ Господь, чтобъ обитало тамъ имя Его.',
        3: 'Не јшь съ нею кислаго, семь дней јшь съ нею опрјсноки, хлјбы бјдствія: ибо ты съ поспјшностію вышелъ изъ земли Египетской, дабы ты помнилъ день исшествія своего изъ земли Египетской во всј дни жизни твоей.',
        4: 'Не должно быть видно у тебя ничто квасное во всемъ предјлј твоемъ въ продолженіи семи дней, и мясо живоюнаго, которое заколешь вечеромъ въ первый день, не должно переночевать до утра.',
        5: 'Не можно закалать Пасхи въ которомъ-нибудь изъ жилищъ твоихъ, которыя Господь, Богъ твой, даетъ тебј.',
        6: 'Но только на томъ мјстј, которое изберетъ Господь, Богъ твой, чтобы обитало тамъ имя Его, закалай Пасху вечеромъ при захожденіи солнца, въ извјстное время, въ которое ты вышелъ изъ Египта.',
        7: 'И испеки и съјшь на томъ мјстј, которое изберетъ Господь, Богъ твой, а на другой день пойди назадъ и иди въ шатры твои.',
        8: 'Шесть дней јшь прјсные хлјбы, а въ седьмый день торжество Господу, Богу твоему; не дјлай тогда никакого дјла.',
        9: 'Семь седьмицъ отсчитай себј; начинай считать семь седьмицъ съ того времени, какъ появится серпъ на жатвј.',
        10: 'Тогда совершай праздникъ седьмицъ Господу, Богу твоему, смотря по усердію руки твоей, сколько ты дашь, чјмъ благословитъ тебя Господь, Богъ твой;',
        11: 'и веселись предъ Господомъ, Богомъ твоимъ, ты, и сынъ твой, и дочь твоя, и слуга твой, и служанка твоя, и левитъ, который въ жилищахъ твоихъ, и пришлецъ, и сирота, и вдова, которые будутъ среди тебя, на мјстј, которое изберетъ Господь, Богъ твой, чтобы обитало тамъ имя Его.',
        12: 'И помни, что былъ ты рабомъ въ Египтј, и старайся исполнять постановленія сіи.',
        13: 'Праздникъ кущей совершай у себя семь дней, когда уберешь съ гумна твоего и изъ точила твоего,',
        14: 'и веселись въ праздникъ твой ты, и сынъ твой, и дочь твоя, и слуга твой, и служанка твоя, и левитъ, и пришлецъ, и сирота, и вдова, которые будутъ въ жилищахъ твоихъ.',
        15: 'Семь дней празднуй Господу, Богу твоему, на мјстј, которое изберетъ Господь: ибо благословитъ тебя Господь, Богъ твой, во всјхъ произведеніяхъ твоихъ и во всякомъ дјлј рукъ твоихъ, и ты будешь только веселиться.',
        16: 'Три раза въ году весь мужескій полъ долженъ являться предъ лице Господа, Бога твоего, на мјсто, которое Онъ изберетъ: въ праздникъ опрјсноковъ, въ праздникъ седьмиць и въ праздникъ кущей, и никто не долженъ являться предъ лице Господа съ пустыми руками,',
        17: 'но каждый съ даромъ въ рукј своей, смотря по благословенію Господа, Бога твоего, какое Онъ далъ тебј.',
        18: 'Во всјхъ жилищахъ твоихъ, которыя Господь, Богъ твой, даетъ тебј, поставь себј судей и надзирателей по колјнамъ твоимъ, которые бы судили народъ судомъ праведнымъ.',
        19: 'Не суди превратно, не смотри на лица и не бери даровъ; ибо дары ослјпляютъ очи мудрыхъ и превращаютъ дјло правыхъ.',
        20: 'Правды, правды ищи, дабы ты быль живъ и получилъ въ наслјдіе землю, которую Господь, Богъ твой, даетъ тебј.',
        21: 'Не сади себј рощи какихъ-либо деревъ подлј жертвенника Господа, Бога твоего, который ты сдјлаешь себј;',
        22: 'и не ставь себј столпа, чего ненавидитъ Господь, Богъ твой,',
    },
    17: {
        1: 'Не приноси въ жертву Господу, Богу твоему, вола, или овцы, на которой будетъ порокъ, или что-нибудь худое: поелику это мерзость для Господа, Бога твоего.',
        2: 'Если найдется среди тебя въ какомъ-либо изъ жилищъ твоихъ, которыя Господь, Богъ твой, даетъ тебј, мущина или женщина, который сдјлаетъ зло предъ очами Господа, Бога твоего, преступитъ завјтъ Его;',
        3: 'и пойдетъ и будетъ служить другимъ богамъ, и поклонится имъ, или солнцу, или лунј, или всему воинству небесному, чего я не повелјлъ;',
        4: 'и тебј возвјщено будетъ и ты услышишь: то ты хорошо разыщи, и если это точная правда, если сдјлана мерзость сія у Израиля:',
        5: 'то выведи мущину того или женщину ту, которые сдјлали зло сіе, къ воротамъ твоимъ, мущина ли то, или женщина, и побей ихъ камнями до смерти.',
        6: 'По свидјтельству двухъ свидјтелей, или трехъ свидјтелей долженъ умереть умерщвляемый: не должно предавать смерти по свидјтельству одного свидјтеля.',
        7: 'Рука свидјтелей должна быть на немъ прежде всјхъ, чтобъ убить его, потомъ рука всего народа, и такимъ образомъ истреби зло изъ среды себя.',
        8: 'Если по какому дјлу затруднительнымъ покажется тебј разсудить между кровію и кровію, между судомъ и судомъ, между побоями и побоями, и будутъ несогласныя мнјнія въ судебныхъ мјстахъ твоихъ: то встань и поди на то мјсто, которое изберетъ Господъ, Богъ твой,',
        9: 'и приди къ священмикамъ, левитамъ или судьј, который будетъ въ тј дни, и спроси ихъ, и они скажутъ тебј, какъ разсудить.',
        10: 'И поступи по слову, какое они скажутъ тебј на томъ мјстј, которое изберетъ Господь, и постарайся исполнить все, чему они научатъ тебя.',
        11: 'По закону, которому научатъ они тебя, и по опредјленію, какое они скажутъ тебј, поступи, и не уклоняйся ни направо, ни налјво отъ того, что они скажутъ тебј.',
        12: 'А кто поступитъ такъ дерзко, что не послушаетъ священника, стоящаго тамъ въ служеніи предъ Господомъ, Богомъ твоимъ, или судіи: тотъ долженъ умереть, и такимъ образомъ истреби зло отъ Израиля;',
        13: 'и весь народъ услышитъ и убоится, и не будетъ впредь поступать дерзко.',
        14: 'Когда ты придешь въ землю, которую Господь, Богъ твой, даетъ тебј, и возьмешь ее въ наслјдіе и поселишься на ней, и скажешь: поставлю я надъ собою царя, подобно прочимъ народамъ, которые вокругъ меня;',
        15: 'то поставь надъ собою царя, котораго изберетъ Господь, Богъ твой; изъ среды братій твоихъ поставь надъ собою царя: не можно тебј поставить надъ собою иноземца, который не братъ тебј.',
        16: 'Только чтобъ онъ не умножалъ себј коней, и не возвращалъ народа въ Египетъ для умноженія коней; ибо Господь сказалъ вамъ: не возвращайтесь болје путемъ симъ;',
        17: 'и чтобъ не умножалъ себј женъ, дабы не развратилось сердце его, и чтобы серебра и золота не умножалъ себј чрезмјрно.',
        18: 'Но когда онъ сядетъ на престолј царства своего, долженъ списать себј списокъ закона сего съ книги, взятой у священниковъ-левитовъ,',
        19: 'и пусть онъ будетъ у него, и пусть онъ читаеть его во всј дни жизни своей; дабы научался бояться Господа, Бога своего, и старался исполнять всј слова закона сего и постановленія сіи;',
        20: 'чтобы не надмевалось сердце его предъ братіями его, и чтобы не уклонялся онъ отъ заповјдей сихъ ни направо, ни налјво; дабы долгое время пребылъ на царствј своемъ онъ и сыны его среди Израиля.',
    },
    18: {
        1: 'Священникамъ-левитамъ, всему колјну Левіину не будетъ части и удјла съ Израилемъ: они должны питаться жертвами Господа и Его частію.',
        2: 'Удјла не будетъ ему между братьями его; Самъ Господь удјлъ его, какъ говорилъ Онъ ему.',
        3: 'Вотъ что должно быть положено священникамъ отъ народа, отъ приносящихъ въ жертву воловъ или овецъ: приносящій жертву долженъ отдавать священнику плечо, челюсти и требуху.',
        4: 'Также начатки хлјба твоего, вина твоего и елея твоего, и начатки шерсти овецъ твоихъ отдавай ему.',
        5: 'Поелику его избралъ Господь, Богъ твой, изъ всјхъ колјнъ твоихъ, чтобы онъ предстоялъ, служа во имя Господа, самъ и сыны его во всј дни.',
        6: 'Если левитъ изъ одного изъ жилищъ твоихъ, изъ которой-нибудь земли сыновъ Израилевыхъ, въ которой онъ жилъ, придетъ по какому-либо желанію души своей на мјсто, которое изберетъ Господь:',
        7: 'то пусть онъ служитъ во имя Господа, Бога своего, такъ, какъ и всј братья его левиты, предстоящіе тамъ предъ Господомъ.',
        8: 'Пусть они пользуются одинаковою частію съ прочими, сверхъ проданнаго имущества отцевъ своихъ.',
        9: 'Когда ты войдешь въ землю, которую даетъ тебј Господь, Богъ твой, тогда не научись дјлать мерзости, какія дјлали народы сіи:',
        10: 'не додженъ находиться у тебя проводящій сына своего или дочь свою чрезъ огонь, прорицатель, гадатель, ворожея, чародјй,',
        11: 'обаятель, призывающій духовъ, волшебникъ и вопрошающій мертвыхъ:',
        12: 'ибо мерзокъ предъ Господомъ всякій дјлающій сіе, и за сіи-то мерзости Господь, Богъ твой, изгоняетъ ихъ отъ лица твоего.',
        13: 'Будь совершенно преданъ Господу, Богу твоему.',
        14: 'Ибо народы сіи, которые ты берешь въ наслјдіе, слушаютъ гадателей и прорицателей; а тебј не то далъ Господь, Богъ твой.',
        15: 'Пророка изъ среды тебя, изъ братьевъ твоихъ, какъ меня, воздвинетъ тебј Господь, Богъ твой: Его слушайте.',
        16: 'Такъ какъ ты просилъ у Господа, Бога твоего, при Хоривј въ день собранія, говоря: да не услышу гласа Господа, Бога моего, и огня сего великаго да не увижу болје, дабы мнј не умереть.',
        17: 'И сказалъ мнј Господь: хорошо, что они говорили.',
        18: 'Я воздвигну имъ пророка изъ среды братьевъ ихъ, какъ тебя, и вложу слова Мои во уста Его, и Онъ будетъ говорить имъ все, что Я повелю Ему.',
        19: 'А кто не послушаетъ словъ Моихъ, которыя Онъ будетъ говорить Моимъ именемъ, съ того Я взыщу.',
        20: 'Но пророка, который дерзнетъ говорить Моимъ именемъ слово, котораго Я не повелјлъ ему говорить, и который будетъ говорить именемъ другихъ боговъ, таковаго пророка предайте смерти.',
        21: 'Если же скажешь въ сердцј твоемъ: какъ мы узнаемъ слово, которое не Господь говорилъ?',
        22: 'Если пророкъ скажетъ именемъ Господа, но слово то не сбудется и не исполнится: то не Господь говорилъ сіе слово; пророкъ сказалъ его по дерзости, не бойся его.',
    },
    19: {
        1: 'Когда Господь, Богъ твой, истребитъ народы, коихъ землю даетъ тебј Господь, Богъ твой, и ты вступишь въ наслјдіе послј нихъ, и поселишься въ городахъ ихъ и домахъ ихъ:',
        2: 'тогда отдјли себј три города среди земли твоей, которую Господь, Богъ твой, даетъ тебј въ наслјдіе.',
        3: 'Устрой себј дорогу и раздјли на три части всю землю твою, которую Господь, Богъ твой, даетъ тебј въ удјлъ; они будутъ служить убјжищемъ всякому убійцј.',
        4: 'И вотъ какой убійца можетъ убјгать туда, и остаться живъ: кто убьетъ ближняго своего безъ намјренія, не бывъ врагомъ ему вчера и третьяго дня.',
        5: 'Напримјръ, если кто пойдетъ съ ближнимъ своимъ въ лјсъ рубить дрова, и размахнется рука его съ топоромъ, чтобъ срубить дерево, и соскочитъ желјзо съ топорища, и попадетъ въ ближняго и онъ умретъ: таковый пусть убјжитъ въ одинъ изъ городовъ тјхъ и будетъ живъ,',
        6: 'дабы мстящій за кровь, въ горячности сердца своего, не погнался за убійцею и не настигъ его, если далекъ будетъ путь, и не убилъ его, между тјмъ какъ не подлежитъ осужденію на смерть, ибо не былъ врагомъ ему вчера и третьяго дня.',
        7: 'Посему Я и далъ тебј повелјніе, говоря: отдјли себј три города.',
        8: 'Когда же Господь, Богъ твой, распространитъ предјлы твои, какъ Онъ клялся отцамъ твоимъ, и дастъ тебј всю землю, которую Онъ објщалъ дать отцамъ твоимъ,',
        9: 'если ты будешь стараться исполнять всј сіи заповјди, которыя я заповјдаю тебј сегодня, любить Господа, Бога твоего, и ходить путями Его во всј дни: тогда къ симъ тремъ городамъ прибавь еще три города;',
        10: 'дабы не проливалась кровь невиннаго среди земли твоей, которую Господь, Богъ твой, даетъ тебј въ удјлъ, и чтобы кровь не была на тебј.',
        11: 'Но если кто, бывъ врагомъ ближнему своему, и злоумышляя на него, возстанетъ на него и убьетъ его до смерти, и убјжитъ въ одинъ изъ городовъ тјхъ:',
        12: 'то старјйшины города его должны послать, чтобы взять его оттуда и передать его въ руки мстящаго за кровь, чтобы онъ умеръ.',
        13: 'Да не пощадитъ его око твое, смой съ Израиля кровь невиннаго, и будетъ тебј хорошо.',
        14: 'Не передвигай межи ближняго твоего, которую положили предки въ удјлј твоемъ, доставшемся тебј въ землј, которую Господь, Богъ твой, даетъ тебј въ наслјдіе.',
        15: 'Недостаточенъ одинъ свидјтель на кого-либо въ какой-нибудь винј, и въ какомъ-нибудь преступленіи и въ какомъ-нибудь грјхј, которымъ онъ согрјшилъ: при свидјтельствј двухъ свидјтелей или при свидјтельствј трехъ свидјтелей состоится всякое дјло.',
        16: 'Если выступитъ противъ кого свидјтель несправедливый, донося на него въ преступленіи:',
        17: 'то пусть предстанутъ оба сіи человјка, у которыхъ есть тяжба, предъ Господа, предъ священниковъ и предъ судей, которые будутъ въ тј дни.',
        18: 'Судіи должны хорошо изслјдовать, и если свидјтель тотъ естъ свидјтель ложный, ложь донесетъ на брата своего:',
        19: 'то сдјлайте ему то, что онъ умышлялъ сдјлать брату своему; и такимъ образомъ истреби зло изъ среды себя.',
        20: 'И прочіе услышатъ, и убоятся, и не станутъ впредь дјлать такого зла среди тебя.',
        21: 'Да не щадитъ око твое: душа за душу, глазъ за глазъ, зубъ за зубъ, рука за руку, нога за ногу.',
    },
    20: {
        1: 'Когда ты пойдешь на войну противъ врага твоего, и увидишь коней и колесницы и народа болје, нежели у тебя: то не бойся ихъ, ибо съ тобою Господь, Богъ твой, Который вывелъ тебя изъ земли Египетской.',
        2: 'Когда же надобно вступить вамъ въ сраженіе, тогда священникъ пусть подойдетъ и говоритъ народу,',
        3: 'и скажетъ ему: слушай, Израиль, вы сегодня вступаете въ сраженіе съ врагами вашими, да не ослабјетъ сердце ваше, не бойтесь, не смущайтесь и не ужасайтесь ихъ:',
        4: 'ибо Господь, Богъ вашъ, идетъ съ вами, чтобы сразиться за васъ съ врагами вашими, чтобы спасти васъ.',
        5: 'Надзиратели же пусть объявятъ народу, и скажутъ: кто построилъ новый домъ и не обновилъ его, тотъ пусть идетъ и возвратится въ домъ свой, дабы не умеръ на сраженіи, и другой не обновилъ его.',
        6: 'И кто насадилъ виноградникъ и не пользовался имъ, тотъ пусть идетъ и возвратится въ домъ свой, дабы не умеръ на сраженіи, и другой не восполъзовался имъ.',
        7: 'И кто обручился съ женою и не взялъ ея, тотъ пусть идетъ и возвратится въ домъ свой, дабы не умеръ на сраженіи, и другой не взялъ ея.',
        8: 'Потомъ надзиратели еще объявятъ народу, и скажутъ: кто боязливъ и малодушенъ, тотъ пусть идетъ и возвратится въ домъ свой, дабы онъ не сдјлалъ робкимъ сердца братьевъ его, какъ его сердце.',
        9: 'Когда надзиратели скажутъ все сіе народу, тогда должны они поставить военныхъ начальниковъ въ вожди народа.',
        10: 'Когда подойдешь къ городу, чтобъ завоевать его, предложи ему миръ.',
        11: 'Если онъ согласится на миръ съ тобою и отворитъ тебј ворота, то весь народъ, который найдется въ немъ, будетъ платить тебј дань и служить тебј.',
        12: 'Если же онъ не согласится на миръ съ тобою и будетъ вести съ тобою войну, то осади его.',
        13: 'И когда Господь, Богъ твой, предастъ его въ руки твои, порази въ немъ весь мужескій полъ остріемъ меча;',
        14: 'только женъ и дјтей, и скотъ, и все, что будетъ въ городј, всю добычу его возьми себј, и пользуйся добычею враговъ твоихъ, которыхъ предалъ тебј Господь, Богъ твой.',
        15: 'Такъ поступай со всјми городами, которые отъ тебя весьма далеко, которые не изъ числа городовъ народовъ сихъ.',
        16: 'А въ городахъ сихъ народовъ, которыхъ землю Господь, Богъ твой, даетъ тебј въ удјлъ, не оставляй въ живыхъ ни одной души.',
        17: 'Но предай ихъ заклятію: Хеттеевъ и Аморреевъ, Хананеевъ и Ферезеевъ, Евеевъ и Іевусеевъ, какъ повелјлъ тебј Господь, Богъ твой;',
        18: 'дабы они не научили васъ дјлать такія же мерзости, какія они дјлали для боговъ своихъ, и дабы вы не грјшили предъ Господомъ, Богомъ вашимъ.',
        19: 'Если долгое время будешь держать въ осадј городъ, чтобы завоевать его и взять его: то не порть деревъ его, и не поднимай на нихъ топора; но јшь плоды съ нихъ, а не руби ихъ: ибо дерево на полј развј человјкъ, чтобъ оно ушло отъ тебя въ крјпость?',
        20: 'Только тј дерева, о которыхъ ты знаешь, что они ничего не приносятъ въ пищу, можешь портить и рубить, и строить укрјпленія противъ города, который ведетъ съ тобою войну, доколј не покоришь его.',
    },
    21: {
        1: 'Если въ землј, которую Господь, Богъ твой, даетъ тебј въ наслјдіе, найденъ будетъ убитый, лежащій на полј, и неизвјстно будеть, кто убилъ его:',
        2: 'то старјйшины твои и судіи твои пусть выйдутъ и измјрятъ разстояніе до городовъ, которые около убитаго;',
        3: 'и старјйшины города того, который будетъ ближайшій къ убитому, пусть возьмутъ телицу, на которой не работали, которая не носила ярма.',
        4: 'И пусть старјйшины того города отведутъ сію телицу къ неизсякающему потоку, гдј земля не разработана и не засјяна, и заколютъ тамъ телицу у потока;',
        5: 'и придутъ священники, сыны Левіины (ибо ихъ избралъ Господь, Богъ твой, служить Себј и благословлять именемъ Господа, и по слову ихъ должно рјшить всякое спорное дјло и всякой причиненный вредъ).',
        6: 'И всј старјйшины города того, ближайшіе къ убитому, пусть умоютъ руки свои надъ телицею зарјзанною у потока.',
        7: 'И скажутъ притомъ: руки наши не пролили крови сей, и гдаза наши не видали;',
        8: 'очисти народъ Твой, Израиля, который Ты, Господи, освободилъ, и не вмјни народу Твоему, Израилю, невинной крови. Тогда они очистятся отъ крови.',
        9: 'Такимъ образомъ должснъ ты смывать у себя кровь невиннаго, когда хочешь дјлать справедливое предъ очами Господа.',
        10: 'Когда выйдешь на войну противъ враговъ твоихъ и Господь, Богъ твой, предастъ ихъ въ руки твои, и возьмешь изъ нихъ въ плјнъ,',
        11: 'и увидишь между плјнными женщину красивую видомъ, и полюбищь ее, и возьмешь ее себј въ жену:',
        12: 'то приведи ее въ домъ свой, и пусть она острижетъ голову свою и раститъ ногти свои,',
        13: 'и сниметъ съ себя плјнническую одежду свою, и живетъ въ домј твоемъ, и оплакиваетъ отца своего и матерь свою въ продолженіи мјсяца; и послј того ты можешь войдти къ ней и сдјлаться ея мужемъ, и она будетъ твоею женою.',
        14: 'Если же она послј не понравится тебј, то отпусти ее, куда она захочетъ, но не продавай за серебро и не порабощай ея: поелику ты смирилъ ее.',
        15: 'Если у кого будутъ двј жены, одна любимая, а другая нелюбимая, и какъ любимая, такъ и нелюбимая родятъ ему сыновей, и первенцемъ будетъ сынъ нелюбимой:',
        16: 'то, при раздјлј сыновьямъ своимъ имјнія своего, онъ не можетъ сыну жены любимой дать первенства предъ первороднымъ сыномъ нелюбимой.',
        17: 'Но первенцемъ долженъ признать сына нелюбимой, дать ему двойную часть изъ всего, что у него найдется: ибо онъ есть начатокъ силы его, ему принадлежитъ право первородства.',
        18: 'Если у кого будетъ сынъ упрямый и непокорный, не повинующійся гласу отца своего и гласу матери своей, и они наказывали его, но онъ не слушаетъ ихъ:',
        19: 'то отецъ его и мать его пусть возьмутъ его и приведутъ его къ старјйшинамъ города своего и къ воротамъ своего мјстопребыванія,',
        20: 'и скажутъ старјйшинамъ города своего: сей сынъ нашъ упрямъ и непокоренъ, не слушаетъ словъ нашихъ, мотъ и пьяница;',
        21: 'тогда всј жители города его пусть побьютъ его камнями до смерти, и такимъ образомъ истреби зло изъ среды себя; и всј Израильтяне услышатъ и убоятся.',
        22: 'Если въ комъ найдется престунленіе достойное смерти, и онъ будетъ умерщвленъ, и ты повјсишь его на деревј:',
        23: 'то тјло его не должно ночевать на деревј, но погреби его въ тотъ же день; ибо повјшенный есть проклятіе Божіе, и не оскверняй земли твоей, которую Господь, Богъ твой, даетъ тебј въ удјлъ.',
    },
    22: {
        1: 'Когда увидишь вола брата твоего, или овцу его заблудившихся, не оставляй ихъ, но возврати ихъ брату твоему.',
        2: 'Если же не близко будеть къ тебј братъ твой, или ты не знаешь его, то прибери ихъ въ домъ свой, и пусть они будутъ у тебя, пока братъ твой не будетъ искать ихъ, и тогда возврати ему ихъ.',
        3: 'Такъ поступай съ осломъ его, такъ поступай съ одеждою его, такъ поступай со всякою потерянною вещію брата твоего, которая будетъ имъ потеряна, и которую ты найдешь; не можно тебј уклоняться отъ сего.',
        4: 'Когда увидишь осла брата твоего или вола его, упадшихъ на пути, не оставляй ихъ, но подними ихъ съ нимъ вмјстј.',
        5: 'На женщинј не должна быть мужеская одежда и мущина не долженъ одјваться въ женское платье, ибо мерзокъ предъ Господомъ, Богомъ твоимъ, всякой дјлающій сіе.',
        6: 'Если попадется тебј на дорогј птичье гнјздо на какомъ-либо деревј, или на землј, и въ немъ птенцы или яица, и мать сидитъ на птенцахъ или на яицахъ, то не бери матери вмјстј съ дјтьми.',
        7: 'Мать отпусти, а дјтей возьми себј, чтобы тебј было хорошо, и чтобы продолжились дни твои.',
        8: 'Если будешь строить новый домъ, то сдјлай перила около кровли твоей, чтобы не пала кровь на домъ твой, когда кто нибудь упадетъ съ него.',
        9: 'Не засјвай виноградника своего разнородными сјменами, чтобы не сдјлать тебј заклятымъ сбора сјмянъ, которыя ты посјешь вмјстј съ плодами виноградника.',
        10: 'Не паши на волј и ослј вмјстј.',
        11: 'Не надјвай одежды, сдјланной изъ разныхъ веществъ, тканной изъ шерсти и льна вмјстј.',
        12: 'Сдјлай себј кисточки на четырехъ краяхъ покрывала твоего, которымъ ты покрываешься.',
        13: 'Если кто возьметъ жену и войдетъ къ ней, и послј возненавидитъ ее,',
        14: 'и будетъ взводить на нее порочныя дјла, и пуститъ о ней худую молву и скажетъ: я взялъ сію жену, и пришелъ къ ней, и не нашелъ у ней дјвства:',
        15: 'то отецъ отроковицы и мать ея пусть возьмутъ и вынесутъ признаки дјвства отроковицы къ старјйшинамъ города къ воротамъ;',
        16: 'и отецъ отроковицы скажетъ старјйшинамъ: дочь мою я отдалъ въ жену сему человјку, и онъ возненавидјлъ ее,',
        17: 'и вотъ онъ взводитъ на нее порочныя дјла, говоря: я не нашелъ у дочери твоей дјвства, но вотъ признаки дјвства дочери моей; и разстелютъ одежду предъ старјйшинами города.',
        18: 'Тогда старјйшины города его пусть возьмутъ мужа и накажутъ его,',
        19: 'и возьмутъ съ него пени сто сиклей серебра и отдадутъ отцу отроковицы за то, что онъ пустилъ худую молву о дјвицј Израильской; она же пусть останется его женою, и онъ не долженъ разводиться съ нею во всю жизнь свою.',
        20: 'Если же сказанное будетъ истинно, и не найдется дјвства у отроковицы:',
        21: 'то отроковицу пусть приведутъ къ дверямъ дома отца ея, и жители города ея побьютъ ее камнями до смерти, поелику она сдјлала срамное дјло среди сыновъ Израиля, блудодјйствовавъ въ домј отца своего; и такимъ образомъ истреби зло изъ среды себя.',
        22: 'Если найденъ будетъ кто лежащій съ женою замужнею: то должно предать смерти обоихъ, и мужа лежавшаго съ женщиною, и женщину, и такимъ образомъ истреби зло отъ Израиля.',
        23: 'Если будетъ молодая дјвица обручена мужу и кто нибудь другой встрјтится съ нею въ городј, и ляжетъ съ нею:',
        24: 'то обоихъ ихъ приведите къ воротамъ того города и побейте ихъ камнями до смерти, отроковицу за то, что она не кричала въ городј, а мущину за то, что онъ опорочилъ жену ближняго своего, и такимъ образомъ истреби зло изъ среды себя.',
        25: 'Если же кто въ полј встрјтится съ отроковицею обрученною, и схвативъ ее, ляжетъ съ нею: то должно предать смерти только мужчину лежавшаго съ нею,',
        26: 'а отроковицј ничего не дјлай, на отроковицј нјтъ преступленія смертнаго: ибо это тоже, какъ еслибы кто возсталъ на ближняго своего и убилъ его.',
        27: 'Ибо онъ встрјтился съ нею въ полј, и хотя отроковица обрученная кричала, но некому было спасти ее.',
        28: 'Если кто нибудь встрјтится съ дјвицею необрученпою, и возьметъ ее, и ляжетъ съ нею, и застанутъ ихъ:',
        29: 'то лежавшій съ нею долженъ дать отцу отроковицы пятьдесятъ сиклей серебра, а она пусть будетъ его женою, потому что онъ опорочилъ ее; во всю жизнь свою онъ не долженъ разводиться съ нею.',
        30: 'Никто не долженъ брать жены отца своего, и открывать край одежды отца своего.',
    },
    23: {
        1: 'У кого раздавленъ или отрјзанъ дјтородный членъ, тотъ не можетъ войти въ общество Господа.',
        2: 'Сынъ блудницы не можетъ войти въ общество Господа, и въ десятомъ родј не можетъ онъ войти въ общество Господа.',
        3: 'Аммонитянинъ и Моавитянинъ не можетъ войти въ общество Господа и въ десятомъ родј, не могутъ они войти въ общество Господа во вјки:',
        4: 'потому что они не встрјтили васъ съ хлјбомъ и водою на пути, когда вы шли изъ Египта, и потому что они наняли противъ тебя Валаама, сына Веорова изъ Пеѕора Месопотамскаго, чтобы проклясть тебя.',
        5: 'Но Господь, Богъ твой, не восхотјлъ послушать Валаама, и Господъ, Богъ твой, проклятіе перемјнилъ въ благословеніе тебј; ибо Господь, Богъ твой, любитъ тебя.',
        6: 'Не навјдывайся о мирј ихъ и о благополучіи ихъ во всј дни твои, во вјки.',
        7: 'Не гнушайся Идумеяниномъ; потому что онъ братъ твой; не гнушайся Египтяниномъ, потому что ты былъ пришельцемъ въ землј его.',
        8: 'Дјти, которые у нихъ родятся въ третьемъ родј, могутъ войти въ общество Господа.',
        9: 'Когда пойдешь въ походъ противъ враговъ твоихъ, берегись всего худаго.',
        10: 'Если у тебя будетъ кто нечистъ отъ случившагося ночью, то онъ долженъ выдти вонъ изъ стана и не входить въ станъ;',
        11: 'а при наступленіи вечера долженъ омыться водою, и по захожденіи солнца можетъ войти въ станъ.',
        12: 'Мјсто должно быть у тебя внј стана, куда бы тебј выходить.',
        13: 'Кромј оружія твоего, должна быть у тебя лопатка; и когда будешь садиться внј стана, выкопай ею яму, и опять зарой испражненіе твое.',
        14: 'Поелику Господь, Богъ твой, ходитъ среди стана твоего, чтобъ избавлять тебя, и предавать тебј враговъ твоихъ: а посему станъ твой долженъ быть святъ, чтобъ Онъ не увидјлъ у тебя чего срамнаго, и не отступилъ отъ тебя.',
        15: 'Не выдавай раба господину его, когда онъ прибјжитъ къ тебј отъ господина своего.',
        16: 'Пусть онъ у тебя живетъ, среди васъ, на мјстј, которое онъ изберетъ, въ какомъ-нибудь изъ жилищъ твоихъ, гдј ему понравится, не притјсняй его.',
        17: 'Не должно быть блудницы изъ дочерей Израилевыхъ, и не должно быть блудника изъ сыновъ Израилевыхъ.',
        18: 'Не вноси платы блудницы и цјны пса въ домъ Господа, Бога твоего, ни по какому објту, ибо то и другое есть мерзость предъ Господомъ, Богомъ твоимъ.',
        19: 'Не отдавай въ ростъ брату твоему ни серебра, ни хлјба, ни чего-либо другаго, что мажно отдавать въ ростъ.',
        20: 'Иноземцу отдавай въ ростъ, а брату твоему не отдавай въ ростъ, чтобы Господь, Богъ твой, благословилъ тебя во всемъ, что проходитъ чрезъ руки твои, на землј, въ которую ты идешь, чтобы взять ее въ наслјдіе.',
        21: 'Если дашь објтъ Господу, Богу твоему, немедленно исполни его: ибо Господь, Богъ твой, взыщетъ его съ тебя, и на тебј будетъ грјхъ.',
        22: 'Если же ты не далъ објта, то не будетъ на тебј грјха.',
        23: 'Что вышло изъ устъ твоихъ, соблюдай и исполняй, когда ты Господу, Богу твоему, објщалъ что отъ усердія, и когда сказалъ сіе устами своими.',
        24: 'Когда войдешь въ виноградникъ ближняго твоего, јшь ягоды до сыта, сколько хочетъ душа твоя, а въ сосудъ твой не клади.',
        25: 'Когда придешь на жатву ближняго твоего, срывай колосья руками твоими, но серпа не заноси на жатву ближняго твоего.',
    },
    24: {
        1: 'Если кто возьметъ жену и сдјлается ея мужемъ, и послј она не будетъ имјть благоволенія въ глазахъ его, потому что онъ находитъ въ ней что-нибудь срамное, и напишетъ ей разводное письмо, и дастъ ей въ руки, и отпуститъ ее изъ дому своего,',
        2: 'и она, вышедши изъ дому его, пойдетъ, и выдетъ за другаго мужа;',
        3: 'но потомъ и сей послјдній мужъ возненавидитъ ее и напишетъ ей разводное письмо, и дастъ ей въ руки, и отпуститъ ее изъ дому своего; или умретъ сей послјдній мужъ ея, взявшій ее себј въ жену:',
        4: 'то не можетъ первый ея мужъ, отпустившій ее, опять взять ее себј въ жену, послј того, какъ она осквернена: поелику сіе есть мерзость предъ Господомъ; и не порочь земли, которую Господь, Богъ твой, даетъ тебј въ удјлъ.',
        5: 'Если кто взялъ жену недавно, то пусть не идетъ на войну, и ничего не должно возлагать на него; пусть онъ остается свободенъ въ домј своемъ въ продолженіи одного года, и увеселяетъ жену свою, которую взялъ.',
        6: 'Никто не долженъ брать въ залогъ верхняго и нижняго жернова; ибо таковый беретъ въ залогъ душу.',
        7: 'Если найдутъ кого, что онъ укралъ кого-нибудь изъ братій своихъ, изъ сыновъ Израилевыхъ, и поработилъ его, и продалъ его: то таковаго вора должно предать смерти, и такимъ образомъ истреби зло изъ среды себя.',
        8: 'Смотри, въ язвј проказы тщательно соблюдай и исполняй все, чему будутъ учить васъ священники левиты; тщательно исполняйте, что я повелјлъ имъ.',
        9: 'Вспомни, какъ Господь, Богъ твой, поступилъ съ Маріамью на пути, когда вы шли изъ Египта.',
        10: 'Если ты ближнему своему дашь что-нибудь въ займы, то не ходи къ нему въ домъ, чтобы взять у него залогъ.',
        11: 'Постой на улицј, а тотъ, которому ты далъ въ займы, вынесетъ тебј залогъ свой на улицу.',
        12: 'Если же онъ будетъ человјкъ бјдный, то ты не ложись спать, имјя у себя, залогъ его;',
        13: 'возврати ему залогъ при захожденіи солнца, чтобы онъ легъ спать въ одеждј своей, и благословилъ тебя: и тебј поставится сіе въ праведность предъ Господомъ, Богомъ твоимъ.',
        14: 'Не обижай наемника, бјднаго и нищаго изъ братій твоихъ или изъ пришельцевъ твоихъ, которые въ землј твоей, въ жилищахъ твоихъ,',
        15: 'Въ тотъ же день отдай плату его, чтобы солнце не зашло прежде того, поелику онъ бјденъ, и ждеть ея душа его: чтобы онъ не возопилъ на тебя ко Господу, и не было на тебј грјха.',
        16: 'Отцы не должны быть наказываемы смертію за дјтей, и дјти не должны быть наказываемы смертію за отцевъ; каждый долженъ быть наказываемъ смертію за свое преступленіе.',
        17: 'Не суди превратно пришельца и сираго, и у вдовы не бери въ залогъ одежды.',
        18: 'Помни, что ты былъ рабомъ въ Египтј, и Господь, Богъ твой, освободилъ тебя оттуда: посему я и повелјваю тебј дјлать сіе.',
        19: 'Когда будешь жать на полј твоемъ, и забудешь снопъ на полј; то не возвращайся взять его: пусть онъ остается пришельцу, сиротј и вдовј, чтобы Господь, Богъ твой, благословилъ тебя во всјхъ дјлахъ рукъ твоихъ.',
        20: 'Когда будешь обивать маслину свою, то не пересматривай за собою вјтвей; пусть остается пришельцу, сиротј и вдовј.',
        21: 'Когда будешь сниматъ плоды въ виноградникј твоемъ, не обирай до чиста за собою: пусть остается пришельцу, сиротј и вдовј.',
        22: 'И помни, что ты былъ рабомъ въ землј Египетской: посему я и повелјваю тебј дјлать сіе.',
    },
    25: {
        1: 'Если будетъ тяжба между людьми, то пусть приведутъ ихъ въ судъ и разсудятъ ихъ, праваго пусть оправдаютъ, а виновнаго осудятъ.',
        2: 'И если виновный достоинъ будетъ побоевъ, то судья пусть прикажетъ положить его и бить при себј, смотря по винј его, по счету.',
        3: 'Сорокъ ударовъ можно дать ему, а не болје, чтобы когда прибавятъ, наказывая его, больше ударовъ сверхъ этого, братъ твой не былъ обезображенъ предъ очами твоими.',
        4: 'Не заграждай рта волу, когда онъ молотитъ.',
        5: 'Если братья живутъ вмјстј, и одинъ изъ нихъ умретъ, не имјя у себя сына: то жена умершаго не должна выходить на сторону за человјка чужаго, но деверь ея долженъ войти къ ней и взять ее себј въ жену, и поступить по правамъ деверя.',
        6: 'И первенецъ, котораго она родитъ, заступитъ имя брата его умершаго, чтобы имя его не изгладилось во Израилј.',
        7: 'Если же онъ не захочетъ взять невјстку свою, то невјстка его пойдетъ къ воротамъ, къ старјйшинамъ, и скажетъ: деверь мой отказывается возставить имя брата своего во Израилј, не хочетъ поступить со мною по правамъ деверя.',
        8: 'Тогда старјйшины города его должны призвать его и уговаривать его, и если онъ стоитъ въ своемъ и скажетъ: не хочу взять ее,',
        9: 'то невјстка его пусть подойдетъ къ нему въ глазахъ старјйшинъ и сниметъ сапогъ съ ноги его, и плюнетъ ему въ лицо его, и потомъ скажетъ: такъ поступаютъ съ человјкомъ, который не созидаетъ дома брату своему.',
        10: 'И нарекутъ ему имя во Израилј: домъ разутаго.',
        11: 'Когда дерутся между собою мужья, и жена одного подойдетъ, чтобъ отнять мужа своего изъ рукъ біющаго его, и протянувъ руку свою, схватитъ его за срамный удъ:',
        12: 'то отсјки руку ея, да не пощадитъ око твое.',
        13: 'Въ кисј твоей не должны быть двоякія гири, большія и меньшія.',
        14: 'Въ домј твоемъ не должна быть двоякая ефа, большая и меньшая.',
        15: 'Гиря у тебя должна быть полная и правильная, и ефа у тебя должна быть полная и правильная, чтобы продолжились твои дни на землј, которую Господь, Богъ твой, даетъ тебј.',
        16: 'Ибо мерзокъ предъ Господомъ, Богомъ твоимъ, всякій дјлающій неправду.',
        17: 'Помни, какъ поступилъ съ тобою Амаликъ на пути, когда вы шли изъ Египта;',
        18: 'какъ онъ встрјтилъ тебя на пути, и побилъ сзади тебя всјхъ ослабјвшихъ, когда ты усталъ и утомился, и не боялся онъ Бога.',
        19: 'Итакъ, когда Господь, Богъ твой, успокоитъ тебя отъ всјхъ враговъ твоихъ со всјхъ сторонъ, на землј, которую Господь, Богъ твой, даетъ тебј въ удјлъ, чтобы наслјдовать ее, изгладь память Амалика изъ поднебесной; не забудь.',
    },
    26: {
        1: 'Когда ты придешь въ землю, которую Господь, Богъ твой, даетъ тебј въ удјлъ, и получишь ее въ наслјдіе и поселишься на ней:',
        2: 'то возьми начатковъ всјхъ плодовъ земли, которые ты получишь отъ земли твоей, которую Господь, Богъ твой, даетъ тебј, и положи въ корзину, и поди на то мјсто, которое Господь, Богъ твой, изберетъ, чтобъ обитало тамъ имя Его.',
        3: 'И приди къ священнику, который будетъ въ тј дни, и скажи ему: сегодня я изъявляю Господу, Богу твоему, что я вошелъ въ ту землю, которую Господь клялся отцамъ нашимъ дать намъ.',
        4: 'Священникъ возъметъ корзину изъ руки твоей, и поставитъ ее предъ жертвевникомъ Господа, Бога твоего;',
        5: 'ты же при семъ скажи предъ Господомъ, Богомъ твоимъ: "отецъ мой былъ блуждающій Арамеанинъ, и пошелъ въ Египетъ и переселился туда съ немногими людьми, и произошелъ тамъ отъ него народъ великій, сильный и многочисленный;',
        6: 'но Египтяне стали худо поступать съ нами, и притјснять насъ, и налагать на насъ тяжкія работы;',
        7: 'тогда мы возопили ко Господу, Богу отцевъ нашихъ, и услышалъ Господь вопль нашъ, и увидјлъ бјдствіе наше, труды наши и угнјтеніе.',
        8: 'И вывелъ насъ Господь изъ Египта рукою сильною и мышцею простертою, посредствомъ великаго ужаса, знаменій и чудесъ,',
        9: 'и привелъ насъ на мјсто сіе, и далъ намъ землю сію, землю, гдј течетъ молоко и медъ.',
        10: 'И нынј се, приношу начатки плодовъ отъ земли, которую Ты, Господи, далъ мнј!" И поставь ее предъ Господомъ, Богомъ твоимъ, и поклонись предъ Господомъ, Богомъ твоимъ,',
        11: 'и веселись о всјхъ благахъ, которыя Господь, Богъ твой, далъ тебј и дому твоему, ты и левитъ и пришлецъ, который будеть у тебя.',
        12: 'Когда ты отдјлишь всј десятины произведеній земли твоей въ третій годъ, годъ десятинъ, и отдашь левиту, пришельцу, сиротј и вдовј, чтобъ они јли въ жилищахъ твоихъ и насытилисъ;',
        13: 'тогда скажи предъ Господомъ, Богомъ твоимъ: я отобралъ отъ дома святыню, и отдалъ ее левиту, пришельцу, сиротј и вдовј, по всјмъ заповјдямъ Твоимъ, которыя Ты заповјдалъ мнј; я не преступилъ заповјдей Твоихъ и не забылъ.',
        14: 'Я не јлъ ея въ горести моей, и не тратилъ ея на нечистое, и не давалъ изъ ней на мертваго; но я повиновался гласу Господа, Бога моего, исполнилъ все, что Ты мнј заповјдалъ.',
        15: 'Воззри изъ святаго жилища Твоего, съ небесъ, и благослови народъ Твой, Израиля, и землю, которую Ты далъ намъ, такъ какъ Ты клялся отцамъ нашимъ, землю, гдј течетъ молоко и медъ.',
        16: 'Въ день сей Господь, Богъ твой, завјщеваетъ тебј исполнять постановленія сіи и законы: соблюдай и исполняй ихъ отъ всего сердца твоего и отъ всей души твоей.',
        17: 'Господу сказалъ ты нынј, что Онъ будетъ твоимъ Богомъ, и что ты будешь ходить путями Его и хранить постановленія Его и заповјди Его и законы Его, и слушать гласа Его.',
        18: 'И Господь сказалъ тебј нынј, что ты будешь собственнымъ Его народомъ, какъ Онъ говорилъ тебј, и чтобы ты хранилъ всј заповјди Его,',
        19: 'и что Онъ поставитъ тебя выше всјхъ народовъ, которые Онъ сотворилъ, въ чести, славј и красотј, и что ты будешь святымъ народомъ у Господа, Бога твоего, какъ Онъ говорилъ.',
    },
    27: {
        1: 'И заповјдалъ Моисей и старјйшины Израилевы народу, говоря: исполняйте всј заповјди, которыя я заповјдаю вамъ сегодня.',
        2: 'И когда перейдете за Іорданъ, въ землю, которую Господь, Богъ твой, даетъ тебј; тогда поставь у себя большіе камни и обмажь ихъ известью;',
        3: 'и напиши на нихъ всј слова закона сего, когда ты перейдешь, чтобы вступить въ землю, которую Господь, Богъ твой, дастъ тебј, въ землю, гдј течетъ молоко и медъ, какъ говорилъ тебј Господь, Богъ отцевъ твоихъ.',
        4: 'Когда перейдете за Іорданъ, поставьте камни тј, какъ я повелјваю вамъ сегодня, на горј Гевалъ, и обмажьте ихъ известью.',
        5: 'И сооруди тамъ жертвенникъ Господу, Богу твоему, жертвенникъ изъ камней, не поднимай на нихъ желјза.',
        6: 'Изъ камней цјльныхъ сооруди жертвенникъ Господу, Богу твоему, и возноси на немъ всесожженія Господу, Богу твоему,',
        7: 'и приноси жертвы благодарственныя, и јшь тамъ, и веселись предъ Господомъ, Богомъ твоимъ.',
        8: 'И напиши на камняхъ всј слова закона сего очень явственно.',
        9: 'И говорилъ Моисей и священники - левиты, всему Израилю и сказали: внимай и слушай, Израиль: въ день сей ты содјлался народомъ Господа, Бога твоего.',
        10: 'Слушай гласа Господа, Бога твоего, и исполняй заповјди Его и постановленія Его, которыя я заповјдаю тебј сегодня.',
        11: 'И заповјдаль Моисей народу въ день тотъ, и сказалъ:',
        12: 'сіи должны статъ на горј Гаризимъ, чтобы благословлять народъ, когда перейдете за Іорданъ: Симеонъ, Левій, Іуда, Иссахаръ, Іосифъ и Веніаминъ.',
        13: 'А сіи должны стать на горј Гевалъ, чтобы произноситъ проклятіе: Рувимъ, Гадъ, Асиръ, Завулонъ, Данъ и Нефѕалимъ.',
        14: 'Левиты возгласятъ и скажутъ всјмъ Израильтянамъ возвышеннымъ голосомъ:',
        15: 'Проклятъ, кто сдјлаетъ изваянный или литой кумиръ, мерзость предъ Господомъ, произведеніе рукъ художника, и поставитъ въ мјстј тайномъ! И весь народъ будетъ отвјчать и скажетъ; аминь.',
        16: 'Проклятъ порицающій отца своего или матерь свою! И весь народъ скажетъ: аминь.',
        17: 'Проклятъ передвигающій межу ближняго своего! И весь народъ скажетъ: аминь.',
        18: 'Проклятъ, кто слјпаго сбиваетъ съ пути! И весь народъ скажетъ: аминь.',
        19: 'Проклятъ, кто превратно судитъ дјло пришельца, сироты и вдовы! И весь народъ скажетъ: аминь.',
        20: 'Проклятъ, кто лежитъ съ женою отца своего, поелику онъ открылъ край одежды отца своего! И весь народъ скажетъ: аминь.',
        21: 'Проклятъ, кто ляжеть съ какимъ-либо скотомъ! И весь народъ скажетъ: аминь.',
        22: 'Проклятъ, кто ляжетъ съ сестрою своею, съ дочерью отца своего, или дочеръю матери своей! И весь народъ скажетъ: аминь.',
        23: 'Проклятъ, кто ляжетъ съ тещею своею! И весь народъ скажетъ: аминь.',
        24: 'Проклятъ, кто тайно убиваетъ ближняго своего! И весь народъ скажетъ: аминъ.',
        25: 'Проклятъ, кто беретъ дары съ тјмъ, чтобъ убить душу, и пролитъ кровь неповинную! И весь народъ скажетъ: аминь.',
        26: 'Проклятъ, кто не исполнитъ словъ закона сего, и не будетъ поступать по нимъ! И весь народъ скажетъ: аминь.',
    },
    28: {
        1: 'Если ты будешь слушать гласа Господа, Бога твоего, тщательно исполнять всј заповјди Его, которыя я заповјдаю тебј сегодня: то Господь, Богъ твой, поставитъ тебя выше всјхъ народъ земли;',
        2: 'и придутъ на тебя всј благословенія сіи и исполнятся на тебј, если будешь слушать гласа Господа, Бога твоего.',
        3: 'Благословенъ будешь въ городј, и благословенъ будешь на полј.',
        4: 'Благословенъ будетъ плодъ чрева твоего, и плодъ земли твоей, и плодъ скота твоего, родившееся отъ воловъ твоихъ, и стада овецъ твоихъ.',
        5: 'Благословена будетъ корзина твоя и квашня твоя.',
        6: 'Благословенъ будешь при входј твоемъ, и благословенъ при выходј твоемъ.',
        7: 'Поразитъ предъ тобою Господь враговъ твоихъ, возстающихъ на тебя; они выступятъ противъ тебя однимъ путемъ, а семью путями побјгутъ отъ тебя.',
        8: 'Пошлетъ Господь тебј благословеніе въ житницахъ твоихъ, и во всемъ, что будетъ проходить чрезъ руки твои; и благословитъ тебя на землј, которую Господь, Богъ твой, даетъ тебј.',
        9: 'Содјлаетъ тебя Господь народомъ святымъ Своимъ, какъ Онъ клялся тебј, если ты сохранишь заповјди Господа, Бога твоего, и будешь ходить путями Его.',
        10: 'И всј народы земли увидятъ, что имя Господне призвано на тебя, и убоятся тебя.',
        11: 'И съ избыткомъ дастъ тебј Господь блага, плодъ чрева твоего, и плодъ скота твоего, и плодъ полей твоихъ, на землј, которую Господь клялся отцамъ твоимъ, дать тебј.',
        12: 'Откроетъ тебј Господь добрую сокровищницу Свою, небо, чтобъ оно дало дождь землј твоей во время свое, и чтобы благословить всј дјла рукъ твоихъ; и будешь давать взаймы многимъ народамъ, а самъ не будешь брать взаймы.',
        13: 'И сдјлаетъ тебя Господь главою, а не хвостомъ, и будешь только на высотј, а не будешь внизу; если будешь повиноваться заповјдямъ Господа, Бога твоего, которыя заповјдаю я тебј сегодня, хранить и исполнять.',
        14: 'Не отступай отъ всјхъ словъ, которыя заповјдаю вамъ сегодня, ни направо, ни налјво, чтобы пойдти вслјдъ другихъ боговъ и служить имъ.',
        15: 'Если же не будешь слушать гласа Господа, Бога твоего, и не будешь стараться исполнять всј заповјди Его и постановленія Его, которыя я заповјдаю тебј сегодня; то придутъ на тебя всј проклятія сіи и постигнутъ тебя.',
        16: 'Проклятъ будешь въ городј, и проклятъ будешь на полј.',
        17: 'Проклята будетъ корзина твоя и квашня твоя.',
        18: 'Проклятъ будетъ плодъ чрева твоего и плодъ земли твоей, родившееся отъ воловъ твоихъ, и стада овецъ твоихъ.',
        19: 'Проклятъ будешь при входј твоемъ, и проклятъ будешь при выходј твоемъ.',
        20: 'Пошлетъ Господь на тебя проклятіе, смятеніе и гибель во всемъ, что ни будетъ проходить чрезъ руки твои, что ты ни будешь дјлать, пока не будешь истребленъ, и погибнешь скоро за злыя дјла свои, за то, что ты оставилъ Меня.',
        21: 'Прилјпитъ Господь къ тебј язву, пока не сгонитъ Онъ тебя съ земли, въ которую ты идешь, чтобы взять ее въ наслјдіе.',
        22: 'Поразитъ тебя Господь чахоткою, горячкою, лихорадкою, воспаленіемъ, засухою, палящимъ вјтромъ, ржавчиною; онј будутъ преслјдовать тебя, пока не погибнешь.',
        23: 'И небеса твои, надъ головою твоею, сдјлаются мјдью, и земля подъ тобою желјзомъ.',
        24: 'Вмјсто дождя Господь посыплетъ на землю твою пыль и прахъ; съ неба падать будетъ на тебя, пока не будешь истребленъ.',
        25: 'Поразитъ тебя Господь предъ врагами твоими; выступишь противъ нихъ однимъ путемъ, а семью путями побјжишь отъ нихъ, и будешь разсјянъ по всјмъ царствамъ земли.',
        26: 'И трупы твои будутъ пищею всјмъ птицамъ небеснымъ и звјрямъ, и никто не будетъ отгонять ихъ.',
        27: 'Поразитъ тебя Господь проказою Египетскою, почечуемъ, коростою и чесоткою, отъ которыхъ ты исцјлиться не возможешъ.',
        28: 'Поразитъ тебя Господь сумасшествіемъ, слјпотою и оцјпененіемъ сердца.',
        29: 'И ты будешь ощупью ходить въ полдень, какъ слјпой ощупью ходитъ во мракј, и не будешь имјть успјха на путяхъ твоихъ, и будешь тјснимъ и обижаемъ всякой день, и никто не защититъ тебя.',
        30: 'Съ женою обручишься, а другой будетъ спать съ нею; домъ построишь, но не будешь жить въ немъ; виноградникъ насадишь, и не будешь имъ пользоваться.',
        31: 'Вола твоего заколютъ въ глазахъ твоихъ, и не будешь јсть его; осла твоего уведутъ отъ тебя, и не возвратятъ тебј; овцы твои отданы будутъ врагамъ твоимъ, и никто не защититъ тебя.',
        32: 'Сыновья твои и дочери твои будутъ отданы другому народу; очи твои будутъ видјть и всякой день томиться, смотря на нихъ, и не будетъ силы въ рукахъ твоихъ.',
        33: 'Плоды земли твоей и всј труды твои будетъ јсть народъ, котораго ты не зналъ; и ты будешь только притјсняемъ и мучимъ во всј дни.',
        34: 'Сойдешь съ ума видя то, что увидятъ глаза твои.',
        35: 'Поразитъ тебя Господь злою проказой на колјнахъ и голеняхъ, отъ которой ты не возможешь исцјлиться, отъ подошвы ноги твоей по самое темя твое.',
        36: 'Отведетъ Господь тебя и царя твоего, котораго ты поставишь надъ собою, къ народу, котораго не зналъ ни ты, ни отцы твои, и тамъ будешь служить другимъ богамъ, деревяннымъ и каменнымъ.',
        37: 'И будешь предметомъ ужаса, притчею и посмјшищемъ для всјхъ народовъ, къ которымъ отведетъ тебя Господь.',
        38: 'Сјмянъ много вынесешь въ поле, а соберешь мало, потому что појстъ ихъ саранча.',
        39: 'Виноградники будешь садить и воздјлывать, а вина не будешь пить, и не соберешь плодовъ, потому что појстъ ихъ червь.',
        40: 'Маслины будутъ у тебя во всјхъ предјлахъ твоихъ, но елеемъ не помажешься, потому что осыплется маслина твоя.',
        41: 'Сыновъ и дочерей родишь, но ихъ не будетъ у тебя, потому что пойдутъ въ плјнъ.',
        42: 'Всјми деревами твоими и плодами земли твоей завладјетъ кузнечикъ.',
        43: 'Пришлецъ, который среди тебя, будетъ возвышаться надъ тобою выше и выше, а ты опускаться будешь ниже и ниже.',
        44: 'Онъ будетъ давать тебј взаймы, а ты не будешь давать ему взаймы; онъ будетъ главою, а ты будешь хвостомъ.',
        45: 'И придутъ на тебя всј проклятія сіи, и будутъ преслјдовать тебя, и постигнутъ тебя, пока не будешь истребленъ, за то, что ты не слушалъ гласа Господа, Бога твоего, и не хранилъ заповјдей Его и постановленій Его, которыя Онъ заповјдалъ тебј.',
        46: 'Онј будутъ знаменіемъ и указаніемъ на тебј и на сјмени твоемъ во вјкъ.',
        47: 'За то, что ты не служилъ Господу, Богу твоему, съ веселіемъ и радостію сердца, при изобиліи всего,',
        48: 'будешь служить врагамъ твоимъ, которыхъ пошлетъ на тебя Господь, въ голодј, и жаждј, и наготј, и во всякомъ недостаткј; онъ возложитъ на шею твою желјзное ярмо, такъ что измучитъ тебя.',
        49: 'Господь пошлетъ на тебя народъ издалека, отъ края земли; какъ орелъ налетитъ народъ, котораго языка ты не разумјешь,',
        50: 'народъ съ свирјпымъ взоромъ, который не уважитъ старца, н юношу не помилуетъ.',
        51: 'Онъ будетъ јсть плодъ скота твоего и плодъ земли твоей, пока не разоритъ тебя, такъ что не оставитъ тебј ни хлјба, ни вина, ни елея, ни рожденнаго отъ воловъ твоихъ, ни стадъ овецъ твоихъ, пока не погубитъ тебя.',
        52: 'И будетъ тјснить тебя во всјхъ жилищахъ твоихъ, пока во всей землј твоей не разрушитъ высокихъ и крјпкихъ стјнъ твоихъ, на которыя ты надјешься; онъ будетъ тјснить тебя во всјхъ жилищахъ твоихъ, во всей землј твоей, которую Господь, Богъ твой, далъ тебј.',
        53: 'И тогда плодъ чрева твоего, плоть сыновъ своихъ и дочерей своихъ, которыхъ Господь, Богъ твой, далъ тебј, будешь јсть въ тјснотј и въ осадј, въ которой стјснитъ тебя врагъ твой;',
        54: 'мужъ изнјженный у тебя, и жившій въ великой роскоши, безжалостнымъ окомъ будетъ взирать на брата своего, и на жену нјдра своего, и на оставшихся дјтей своихъ, которые останутся у него.',
        55: 'И не дастъ ни одному изъ нихъ плоти дјтей своихъ, которыхъ онъ јстъ, потому что у него не останется ничего въ стјсненіи и въ осадј, въ которой стјснитъ тебя врагъ твой во всјхъ жилищахъ твоихъ.',
        56: 'Женщина, жившая у тебя въ нјгј и роскоши, которая никогда ноги своей не ставила на землю по причинј роскоши и изнјженности, будетъ безжалостнымъ окомъ смотрјть на мужа, который на лонј ея, и на сына своего, и на дочь свою.',
        57: 'И не дастъ имъ послјда выходящаго изъ среды ногъ ея, и дјтей своихъ, которыхъ она родитъ, потому что она при недостакј всего, тайно будетъ јсть ихъ, въ стјсненіи и осадј, въ которой стјснитъ тебя врагъ твой въ жилищахъ твоихъ.',
        58: 'Если не будешь стараться исполнять всј слова закона сего, написанныя въ книгј сей, и не убоишься славнаго и страшнаго сего имени, Господа, Бога твоего:',
        59: 'то Господь поразитъ тебя и потомство твое необычайными язвами, язвами великими и постоянными, и болјзнями злыми и постоянными.',
        60: 'И обратитъ на тебя всј язвы Египетскія, которыхъ ты боялся, и онј прилипнутъ къ тебј.',
        61: 'И всякую болјзнь, и всякую язву, не написанную въ книгј закона сего Господь наведетъ на тебя, доколј не будешь истребленъ.',
        62: 'И останется васъ немного, вмјсто того, чтобы вы множествомъ подобны были звјздамъ небеснымъ, ибо ты не слушалъ гласа Господа, Бога твоего.',
        63: 'И какъ пріятно было Господу дјлать вамъ добро и умножать васъ, такъ пріятно будетъ Господу погублять васъ и истреблять васъ, и извержены будете изъ земли, которую ты идешь взять въ наслјдіе.',
        64: 'И разсјетъ тебя Господь по всјмъ народамъ, отъ края земли до края земли, и будешь тамъ служить другимъ богамъ, которыхъ не зналъ ни ты, ни отцы твои, деревяннымъ и каменнымъ.',
        65: 'Но и между народами сими не успокоишься, и не будетъ мјста упокоенія для ноги твоей, но Господь дастъ тебј тамъ трепещущее сердце, томящіеся очи и скорбящую душу.',
        66: 'Жизнь твоя будетъ висјть предъ тобою, и будешь бояться ночью и днемъ, и не будешь увјренъ въ жизни твоей,',
        67: 'Въ боязни сердца твоего, которою ты будешь объятъ, и смотря глазами своими на то, что ты увидишь, поутру ты скажешь: о еслибы пришелъ вечеръ! а вечеромъ скажешь: о еслибы наступило утро!',
        68: 'Возвратитъ тебя Господь въ Египеть на корабляхъ тјмъ путемъ, о которомъ я сказалъ тебј: ты уже не увидишь его; и тамъ будете продаваться врагамъ своимъ въ рабовъ и въ рабынь, и никто не купитъ васъ.',
    },
    29: {
        1: 'Вотъ слова завјта, который Господь повелјлъ Моисею поставить съ сынами Израилевыми въ землј Моавитской, кромј завјта, который Господь поставилъ съ ними на Хоривј.',
        2: 'Моисей воззвалъ ко всему Израилю, и сказалъ имъ: Вы видјли все, что сдјлалъ Господь предъ очами вашими въ землј Египетской съ Фараономъ, и всјми рабами его и всею землею его:',
        3: 'велякія оныя казни, которыя видјли глаза твои, и великія оныя знаменія и чудеса.',
        4: 'Но до сего дня ве далъ вамъ Господь сердца, чтобы разумјть, очей, чтобы видјть, и ушей, чтобы слышать.',
        5: 'Сорокъ лјтъ я водилъ васъ по пустынј, и одежды ваши иа васъ не обветшали, и обувь твоя не обветшала на ногј твоей.',
        6: 'Хлјба вы не јли и вина и напитковъ не пили, дабы вы знали, что Я Господь, Богъ вашъ.',
        7: 'И когда пришли вы на мјсто сіе, выступилъ противъ насъ Сигонъ, царь Есевонскій, и Огъ царь Васанскій, чтобы сразиться съ нами, и мы поразили ихъ,',
        8: 'и взяли землю ихъ, и отдали ее въ удјлъ колјну Рувимову и Гадову, и половинј колјна Манассіина.',
        9: 'Итакъ храните слова завјта сего, и исполняйте ихъ, чтобы благоразумно поступали во всемъ, что ни будете дјлать.',
        10: 'Всј вы сегодня стоите предъ лицемъ Господа, Бога вашего, начальники ваши, колјна ваши, старјйшины ваши, надзиратели ваши, всј Израильтяне,',
        11: 'дјти ваши, жены ваши, и пришельцы твои, находящіеся въ станј твоемъ, отъ сјкущаго дрова твои до черпающаго воду твою.',
        12: 'Чтобы принять тебј завјтъ Господа, Бога твоего, съ его заклятіемъ, который Господь, Богъ твой, сегодня поставляетъ съ тобою,',
        13: 'дабы сдјлать тебя сегодня Его народомъ, и Онъ будетъ тебј Богомъ, какъ Онъ говорилъ тебј, и какъ клялся отцамъ твоимъ, Аврааму, Исааку и Іакову.',
        14: 'Не съ вами только одними я поставляю сей завјтъ съ симъ заклятіемъ,',
        15: 'но какъ съ тјми, которые сегодня здјсь съ нами стоятъ предъ лицемъ Господа, Бога нашего, такъ и съ тјми, которыхъ нјтъ здјсь съ нами сегодня.',
        16: 'Вы знаете, какъ мы жили въ землј Египетской, и какъ мы проходили посреди народовъ, чрезъ которые вы прошли,',
        17: 'и видјли мерзости ихъ, и кумиры ихъ, деревянные и каменные, серебряные и золотые, которые находятся у нихъ.',
        18: 'Берегитесь, чтобы между вами не было мужчины или женщины, или племени или колјна, которое бы нынј уклонило сердце свое отъ Господа, Бога нашего, и пошло служить богамъ тјхъ народовъ; чтобы между вами не было корня, произращающаго ядъ и полынь,',
        19: 'такого человјка, который бы, услышавъ слова проклятія сего, похвалялся въ сердцј своемъ, говоря: "я буду счастливъ, не смотря ва то, что буду ходить по произволу сердца моего", дабы такимъ образомъ не погубить и сытаго и голоднаго.',
        20: 'Не восхощетъ Господь простить таковому, но тотчасъ возгорится гнјвъ Господа и ярость его на такого человјка, и падетъ на него все проклятіе, написанное въ сей книгј, и изгладитъ Господь имя его изъ поднебесной;',
        21: 'и отдјлитъ его Господь на погибель отъ всјхъ колјнъ Израилевыхъ, сообразно со всјми проклятіями завјта, написанными въ сей книгј закона.',
        22: 'И скажетъ послјдующій родъ, дјти ваши, которые будутъ послј васъ, и чужеземецъ, который придетъ изъ земли дальней, увидјвъ пораженіе земли сей и наказанія, которыми измождитъ ее Господь:',
        23: 'какъ вся земля выгорјла отъ сјры и соли, такъ что не сјютъ на ней, и не произращаетъ она ничего и не выходитъ на ней никакая трава, какъ по истребленіи Содома и Гоморра, Адмы и Севоима, которые ниспровергъ Господь во гнјвј Своемъ и въ ярости Своей;',
        24: 'и скажутъ всј народы: за что Господь такъ поступилъ съ сею землею? за что возгорјлся великій гнјвъ сей?',
        25: 'И скажутъ: за то, что они оставили завјтъ Господа, Бога отцевъ своихъ, который Онъ поставилъ съ ними, когда вывелъ ихъ изъ земли Египетской.',
        26: 'И пошли и стали служить другимъ богамъ и поклоняться имъ, богамъ, которыхъ они не знали, и которыхъ Онъ не назначалъ имъ:',
        27: 'за то возгорјлся гнјвъ Господа на землю сію, и навелъ Онъ на нее всј проклятія, написанныя въ сей книгј;',
        28: 'и извергнулъ ихъ Господь изъ земли ихъ въ гнјвј, ярости и великомъ негодованіи, и повергъ ихъ на другую землю, какъ нынј видимъ.',
        29: 'Сокрытое принадлежитъ Господу, Богу нашему, а открытое намъ и сынамъ нашимъ до вјка, чтобы мы исполняли всј слова закона сего.',
    },
    30: {
        1: 'Когда придетъ на тебя все сіе, благословеніе и проклятіе, которыя изложилъ я тебј, и ты среди всјхъ народовъ, къ которымъ изгонитъ тебя Господь, Богъ твой, обратишься къ сердцу твоему,',
        2: 'и обратишься ко Господу, Богу твоему, и будешь слушать гласа Его во всемъ, что я завјщаваю тебј сегодня, ты и сыны твои отъ всего сердца твоего, и отъ всей души твоей:',
        3: 'тогда Господь, Богъ твой, возвратитъ плјнныхъ твоихъ, и умилосердится надъ тобою, и опять соберетъ тебя отъ всјхъ народовъ, между которыми разсјетъ тебя Господь, Богъ твой.',
        4: 'Хотя бы ты былъ разсјянъ до края неба, и оттуда соберетъ тебя Господь, Богъ твой, и оттуда возьметъ тебя,',
        5: 'и приведетъ тебя Господь, Богъ твой, въ землю, которою владјли отцы твои, и получишь ее въ наслјдіе, и облагодјтельствуетъ тебя, и размножитъ тебя болје отцевъ твоихъ;',
        6: 'и обрјжетъ Господь, Богъ твой, сердце твое, и сердце потомства твоего, чтобы ты любилъ Господа, Бога твоего, отъ всего сердца твоего, и отъ всей души твоей, дабы жить тебј.',
        7: 'Тогда Господь, Богъ твой, всј проклятія сіи обратитъ на враговъ твоихъ и ненавидящихъ тебя, которые гнали тебя.',
        8: 'А ты обратишься и будешь слушать гласа Господа, и исполнять всј заповјди Его, которыя заповјдую тебј сегодня.',
        9: 'Со избыткомъ дастъ тебј Господь, Богъ твой, счастіе во всякомъ дјлј рукъ твоихъ, въ плодј чрева твоего, въ плодј скота твоего, въ плодј земли твоей; ибо снова радоваться будетъ Господь о тебј, благодјтельствуя тебј, какъ Онъ радовался объ отцахъ твоихъ,',
        10: 'если будешь слушать гласа Господа, Бога твоего, соблюдая заповјди Его и постановленія Его, написанныя въ сей книгј закона, и если обратишься ко Господу, Богу твоему, всемъ сердцемъ твоимъ, и всею душею твоею.',
        11: 'Заповјдь сія, которую я заповјдаю тебј сегодня, не сокрыта отъ тебя и не удалена;',
        12: 'она не на небј, чтобы нужно было говорить: кто бы намъ взошелъ на небо, и взялъ ее намъ, и далъ намъ услышать ее, и мы исполнили бы ее?',
        13: 'И не за моремъ она, чтобы нужно было говорить: кто бы намъ сходилъ за море, и взялъ ее намъ, и далъ намъ услышать ее, и мы исполнили бы ее?',
        14: 'Но слово сіе весьма близко къ тебј; оно въ устахъ твоихъ и въ сердцј твоемъ, чтобы ты исполнялъ его.',
        15: 'Смотри! Я сегодня предложилъ тебј жизнь и добро, смерть и зло.',
        16: 'Ибо я заповјдаю тебј сегодня любить Господа, Бога твоего, ходить по путямъ Его, и исполнять заповјди Его, и постановленія Его, и законы Его: тогда ты будешь жить и размножишься, и благословитъ тебя Господь, Богъ твой, на землј, въ которую ты идешь, чтобы получить ее въ наслјдіе.',
        17: 'Если же отвратится сердце твое и не будешь слушать, и заблудишь, и станешь поклоняться другимъ богамъ и будешь служить имъ:',
        18: 'то я возвјщаю вамъ сегодня, что вы погибнете, и не долго пробудете на землј, въ которую ты переходишь за Іорданъ, чтобы пойдти взять ее въ наслјдіе.',
        19: 'Во свидјтельство на васъ призываю сегодня небо и землю; жизнь и смерть предложилъ Я тебј, благословеніе и проклятіе: избери жизнь, дабы жилъ ты и потомство твое,',
        20: 'любилъ Господа, Бога твоего, слушалъ гласа Его, и прилјплялся къ Нему; ибо сіе есть жизнь твоя и долговременное пребываніе твое на землј, которую Господь съ клятвою објщалъ отцамъ твоимъ, Аврааму, Исааку и Іакову, дать имъ.',
    },
    31: {
        1: 'И пошелъ Моисей и говорилъ слова сіи всему Израилю.',
        2: 'И сказалъ имъ: теперь мнј сто двадцать лјтъ, я не могу уже выходить и входить, и Господь сказалъ мнј: ты не перейдешь за Іорданъ сей.',
        3: 'Господь, Богъ твой, Онъ перейдетъ предъ тобою, Онъ истребитъ народы сіи, отъ лица твоего, и ты овладјешь ими; Іисусъ, онъ перейдетъ предъ тобою, какъ говорилъ Господь.',
        4: 'И поступитъ Господь съ ними такъ же, какъ Онъ поступилъ съ Сигономъ и Огомъ, царями Аморрейскими, и съ землею ихъ, истребивъ ихъ.',
        5: 'Когда Господь предастъ ихъ вамъ, тогда поступите съ ними по всјмъ заповјдямъ, какія заповјдалъ я вамъ.',
        6: 'Будьте тверды и мужественны, не бойтесь и не страшитесь ихъ; ибо Господь, Богъ твой, Самъ пойдетъ съ тобою, не отступитъ отъ тебя и не оставитъ тебя.',
        7: 'И призвалъ Моисей Іисуса, и предъ очами всјхъ Израильтянъ сказалъ ему: будь твердъ и мужественъ, ибо ты войдешь съ народомъ симъ въ землю, о которой Господь клялся отцамъ его дать ему, и ты раздјлишь ее на удјлы ему.',
        8: 'Господь Самъ пойдетъ предъ тобою, Самъ будетъ съ тобою, не отступитъ отъ тебя, и не оставитъ тебя: не бойся и не ужасайся.',
        9: 'И написалъ Моисей законъ сей, и отдалъ его священникамъ, сынамъ Левіинымъ, носящимъ ковчегъ завјта Господня, и всјмъ старјйшинамъ Израиля.',
        10: 'И завјщалъ имъ Моисей, и сказалъ: по прошествіи семи лјтъ, въ годъ прощенія, въ праздникъ кущей,',
        11: 'когда весь Израиль придетъ явиться предъ лице Господа, Бога твоего, на мјсто, которое Онъ изберетъ, читай сей законъ предъ всјмъ Израилемъ въ слухъ его.',
        12: 'Собери народъ, мужей, женъ и дјтей, и пришельцевъ твоихъ, которые будутъ въ жилищахъ твоихъ, чтобъ они слушали, и чтобъ учились и боялись Господа, Бога вашего, и старались исполнять всј слова закона Его,',
        13: 'Тогда и сыны ихъ, которые не знаютъ сего, услышатъ и научатся бояться Господа, Бога вашего, во всј дни, пока вы будете жить на землј, въ которую вы переходите за Іорданъ, чтобы взять ее въ наслјдіе.',
        14: 'И сказалъ Господь Моисею: вотъ дни твои приближились къ смерти, призови Іисуса, и станьте въ скиніи собранія, и Я дамъ ему наставленія. И пришелъ Моисей и Іисусъ, и стали въ скиніи собранія.',
        15: 'И явился Господь въ скиніи, въ столпј облачномъ, и сталъ столпъ облачный у дверей скиніи.',
        16: 'И сказалъ Господь Моисею: вотъ ты почіешь съ отцами твоими; и станетъ народъ сей блудно ходить въ слјдъ чужихъ боговъ той земли, въ которую онъ вступаетъ, и оставитъ Меня, и нарушитъ завјтъ Мой, который Я поставилъ съ ними.',
        17: 'И возгорится гнјвъ Мой на него въ тотъ день. и Я оставлю его, и сокрою лице Мое отъ него, и онъ истребленъ будетъ, и постигнутъ его многія бјдствія и скорби, и скажетъ онъ въ тотъ день: не потому ли постигли меня сіи бјдствія, что нјтъ Бога моего среди меня?',
        18: 'Я скрою лице Мое въ тотъ день, за всј беззаконія его, которыя онъ сдјлаетъ, обратившись къ другимъ богамъ.',
        19: 'Итакъ напишите себј пјснь сію, и научи ей сыновъ Израилевыхъ и вложи ее въ уста ихъ, чтобы пјснь сія была Мнј свидјтельствомъ на сыновъ Израилевыхъ.',
        20: 'Ибо Я введу ихъ въ землю, такъ какъ Я клялся отцамъ ихъ, гдј течетъ молоко и медъ, и они будутъ јсть, и насытятся, и утучнјютъ, и обратятся къ другимъ богамъ, и будутъ служить имъ, а Меня отвергнутъ, и нарушатъ завјтъ Мой.',
        21: 'И когда постигнутъ ихъ многія бјдствія и скорби, тогда пјснь сія будетъ противъ нихъ свидјтельствомъ; ибо она не выйдетъ изъ устъ потомства ихъ. Ибо Я знаю мысли ихъ, которыя они имјютъ нынј, прежде нежели Я ввелъ ихъ въ землю, о которой Я клялся.',
        22: 'И написалъ Моисей пјснь сію въ тотъ день и научилъ ей сыновъ Израилевыхъ.',
        23: 'И заповјдалъ Господь Іисусу сыну Навину и сказалъ: будь твердъ и мужественъ, ибо ты введешь сыновъ Израилевыхъ въ землю, о которой Я клялся имъ, и Я буду съ тобою.',
        24: 'Когда Моисей вписаль въ книгу всј слова закона сего до конца:',
        25: 'тогда Моисей далъ повелјніе левитамъ, носящимъ ковчегь завјта Господня, и сказалъ:',
        26: 'возьмите сію книгу закона и положите ее съ боку ковчега завјта Господа, Бога вашего, и она тамъ будетъ свидјтельствомъ на васъ.',
        27: 'Ибо я знаю упорство твое и жестоковыйность твою: вотъ и тогда, когда я живу съ вами нынј, вы упорны противъ Господа, кольми паче по смерти моей.',
        28: 'Соберите ко мнј всјхъ старјйшинъ колјнъ вашихъ, и надзирателей вашихъ, и я скажу вслухъ ихъ слова сіи, и призову во свидјтельство на нихъ небо и землю.',
        29: 'Ибо я знаю, что по смерти моей вы развратитесь и уклонитесь отъ пути, который я завјщалъ вамь, и въ послјдствіи времени встрјтятъ васъ бјдствія за то, что вы будете дјлать беззаконіе, предъ очами Господа, раздражая Его дјлами рукъ своихъ.',
        30: 'И изрекъ Моисей вслухъ всего собранія Израильтянъ слова пјсни сей до конца.',
    },
    32: {
        1: 'Внемлите небеса, и я начну говорить; И слушай земля слова устъ моихъ.',
        2: 'Польется, какъ дождь, ученіе мое; Покаплетъ, какь роса, слово мое, какъ мелкій дождь на зелень, какъ ливень на траву.',
        3: 'Ибо имя Господа провозглашаю; Воздайте славу Богу нашему.',
        4: 'Твердыня! совершенны дјла Его, ибо всј пути его праведны. Богъ истины, и нјтъ неправды в Немъ, Онъ правдивъ и вјренъ.',
        5: 'Но они развратились предъ Нимъ, они не дјти Его по своимъ порокамъ, родъ строптивый и вјроломный.',
        6: 'Сіе ли воздаете вы Господу, народъ глупый и несмысленный? Не Онъ ли Отецъ твой, Который усвоилъ тебя, сотворилъ тебя, и устроилъ тебя?',
        7: 'Вспомни дни древніе, помыслите о лјтахъ прежнихъ родовъ, спроси отца своего, и возвјститъ тебј, старцевъ твоихъ, и они скажутъ тебј.',
        8: 'Когда Всевышній давалъ удјлы народамъ, и разселялъ сыновъ человјческихъ: Тогда поставилъ предјлы народовъ по числу сыновъ Израилевыхъ.',
        9: 'Ибо часть Господня народъ Его; Іаковъ наслјдственный удјлъ Его.',
        10: 'Онъ обрјлъ его въ пустынј, въ степи печальной и дикой; Ограждалъ его, смотрјлъ за нимъ, хранилъ его, какъ зјницу ока Своего.',
        11: 'Какъ орелъ вызываетъ гнјздо свое, носится надъ птенцами своими, расширяетъ крылья свои, беретъ ихъ и поднимаетъ ихъ на перьяхъ своихъ:',
        12: 'Такъ Господь одинъ водилъ его, и не было съ Нимъ чужаго бога,',
        13: 'Онъ вознесъ его на высоту земли, и кормилъ произведеніями полей, и питалъ его медомъ изъ камня, и елеемъ отъ скалы кремнистой,',
        14: 'Сыромъ коровьимъ и молокомъ овечьимъ, и тукомъ агнцевъ и овновъ Васанскихъ и козловъ, и тукомъ пшеницы, и ты пилъ вино, кровь виноградныхъ ягодъ.',
        15: 'И утучнјлъ Израиль, и упоренъ сталъ; Ты утучнјлъ, отолстјлъ и разжирјлъ, и оставилъ онъ Бога, Который сотворилъ его, и презрјлъ твердыню спасенія своего.',
        16: 'Богами чуждыми они раздражили Его, и мерзостями разгнјвали Его.',
        17: 'Приносили жертвы бјсамъ, а не Богу, Богамъ, которыхъ они не знали, новымъ, которые пришли отъ сосјдей и которыхъ не боялись отцы ваши.',
        18: 'А Заступника, родившаго тебя, ты забылъ, и не помнилъ Бога, произведшаго тебя.',
        19: 'Господь увидјлъ, и пренебрегъ въ негодованіи Сыновъ Своихъ и дочерей Своихъ.',
        20: 'И сказалъ: сокрою лице Мое отъ нихъ; Увижу, какой будетъ конецъ ихъ: Ибо они родъ развращенный, дјти, въ которыхъ нјтъ вјрности.',
        21: 'Они раздражили меня не богомъ, суетными своими огорчили меня: И Я раздражу ихъ не народомъ, народомъ невјжественнымъ огорчу ихъ.',
        22: 'Ибо огнь возгорјлся во гнјвј Моемъ, и жжетъ до ада преисподняго, и поядаетъ землю и произведенія ея, и попаляетъ основанія горъ.',
        23: 'Соберу на нихъ бјдствія, и истощу на нихъ стрјлы Мои.',
        24: 'Будутъ истощены голодомъ, истреблены хищными птицами и лютою заразою, и пошлю на нихъ зубы звјрей, и ядъ ползающихъ по землј.',
        25: 'Отвнј будетъ губить дјтей ихъ мечъ, а въ домахъ ужасъ, и юношу, и дјвицу, и груднаго младенца, и покрытаго сјдиною старца.',
        26: 'Я сказалъ бы: разсыплю ихъ, изглажу изъ среды человјковъ память о нихъ,',
        27: 'Если бы я не опасался огорченія отъ враговъ; Чтобы непріятели его не возмнили и не сказали: наша рука высока. И не Господь сдјлалъ все сіе',
        28: 'Ибо они народъ потерявшій разсудокъ, и нјтъ въ нихъ смысла.',
        29: 'О, если бы они сдјлались мудрыми, подумали о семъ, уразумјли, что съ ними будетъ!',
        30: 'Какъ бы могъ одинъ преслјдоватъ тысячу, и двое прогонять тму, если бы Заступникъ ихъ не предалъ ихъ, и Господь не отдалъ ихъ!',
        31: 'Ибо заступникъ ихъ не таковъ, какъ нашъ Заступникъ; Сами враги наши могутъ судить.',
        32: 'Ибо виноградъ ихъ отъ виноградеой лозы Содомской и съ полей Гоморрскихъ; Ягоды ихъ ягоды ядовитыя, грозды ихъ горькія;',
        33: 'Вино ихъ ярость драконовъ и гибельный ядъ аспидовъ.',
        34: 'Не сокрыто ли сіе у Меня? Не запечатано ли въ сокровищницахъ Моихъ?',
        35: 'У мена отмщеніе и воздаяніе, когда поколеблется нога ихъ ибо близокъ день погибели ихъ, скоро наступитъ уготованное для нихъ.',
        36: 'Ибо Господь будетъ судить народъ Свой, и надъ рабами Своими умилосердится, когда онъ увидитъ, что рука ихъ ослабјла, и не стало ни зависящаго, ни не зависимаго.',
        37: 'Тогда скажетъ: гдј боги ихъ, твердыня, на которую они надјялись,',
        38: 'Которые јли тукъ жертвъ ихъ, пили вино возліяній ихъ? Пусть они возстанутъ и помогутъ вамъ, пусть будутъ для васъ покровомъ!',
        39: 'Видите нынј, что это Я, Я, и нјтъ Бога кромј Меня. Я умерщвлю и оживлю, Я поражу и Я исцјлю, и никто не избавитъ отъ руки Моей.',
        40: 'Я подьемлю къ небесамъ руку Мою, и говорю: живу Я въ вјкъ;',
        41: 'Изострю сверкающій мечъ Мой, и рука Моя пріиметъ судъ, отмщу врагамъ Моимъ и ненавидящимъ Меня воздамъ.',
        42: 'Упою стрјлы Мои кровію, и мечъ Мой насытится плотію, кровію убитыхъ и плјнныхъ, головами начальниковъ врага.',
        43: 'Возвеселитесь язычники, народъ Его: Ибо Онъ мститъ за кровь рабовъ Своихъ, и воздаетъ мщеніе врагамъ Своимъ, и очищаетъ землю, народъ Свой.',
        44: 'И пришелъ Моисей, и изрекъ всј слова пјсни сей вслухъ народа, онъ и Іисусъ сынъ Навинъ.',
        45: 'Когда Моисей изрекъ всј слова сіи всему Израилю,',
        46: 'тогда сказалъ имъ: положите на сердце ваше всј слова, которыя я объявилъ вамъ сегодня, и завјщавайте ихъ дјтямъ своимъ, чтобъ они старались исполнять всј слова закона сего.',
        47: 'Ибо это не пустое для васъ; но это жизнь ваша, и чрезъ сіе вы долгое время пробудете на той землј, въ которую вы переходите за Іорданъ, чтобы взять ее вь наслјдіе.',
        48: 'И говорилъ Господь Моисею въ тотъ же самый день, и сказалъ:',
        49: 'взойди на сію гору Аваримъ, на гору Нево, которая въ землј Моавитской, противъ Іерихома и посмотри на землю Ханаанскую, которую Я даю во владјніе сынамъ Израилевымь.',
        50: 'И умри на горј, на которую ты взойдешь, и отойди къ народу своему, такъ какъ умеръ Ааронъ, братъ твой, на горј Оръ, и отошелъ къ народу своему,',
        51: 'за то, что вы согрјшили противъ Меня среди сыновъ Израилевыхъ при водахъ Меривы въ Кадесј, въ пустынј Цинъ, за то, что не явили святости Моей среди сыновъ Израилевыхъ.',
        52: 'Предъ собою ты увидишь землю, а не войдешь туда, въ землю, которую Я даю сынамъ Израилевымъ.',
    },
    33: {
        1: 'Вотъ благословеніе, которымъ Моисей, человјкъ Божій, благословилъ сыновъ Израилевыхъ предъ смертію своею.',
        2: 'Онъ сказалъ: Господь пришелъ отъ Синая, возсіялъ для нихъ отъ Сеира, возблисталъ отъ горы Фарана, и шелъ изъ среды темъ святыхъ, одесную Его огнь закона для нихъ.',
        3: 'Онъ любитъ также народы; Всј святые его въ рукј Твоей; И шли они въ слјдъ ногъ Твоихъ, получили долю изъ словъ Твоихъ.',
        4: 'Законъ далъ намъ Моисей, наслјдіе обществу Іаковлеву.',
        5: 'Онъ царь Израиля, когда собираются главы народа, вкупј колјна Изранлевы.',
        6: 'Да живетъ Рувимъ и да не умретъ, когда будугь люди его малочисленны.',
        7: 'Но Іудј сказалъ сіе: Услыши, Господи, гласъ Іуды, и приведи его къ народу его, руками Своими: Да защититъ Онъ его, и будь помощпикомъ противъ враговъ его.',
        8: 'И о Левіи сказалъ: Туммимъ Твой и уримъ Твой на святомъ мужј Твоемъ, котораго Ты искусилъ въ Массј, съ которымъ Ты препирался при водахъ Меривы,',
        9: 'Который говоритъ объ отцј своемъ и о матери своей: на нихъ не смотрю, и братьевъ своихъ чуждается, и сыновей своихъ не знаетъ. Ибо они слова Твои хранятъ, и завјтъ Твой соблюдаютъ.',
        10: 'Учатъ законамъ Твоимъ Іакова, и заповјдямъ Твоимъ Израиля, возлагаютъ куреніе предъ лице Твое, и всесожженія на жертвенникъ Твой.',
        11: 'Благослови, Господи, силу его, и о дјлј рукъ его благоволи, порази чресла возстающихъ на него и ненавидящихъ его, чтобъ они не могли стоятъ.',
        12: 'О Веніаминј сказалъ: Возлюбленный Господомъ обитаетъ у него безопасно; Богъ покровительствуетъ ему всякой день, и обитаетъ между раменами Его.',
        13: 'О Іосифј сказалъ: Благословенна Господомъ земля его, драгоцјнными дарами неба, росою, и дарами бездны, лежащей внизу,',
        14: 'Драгоцјнными плодами солнца, и драгоцјнными произведеніями мјсяцевъ;',
        15: 'Превосходнјйшими произведеніими горъ древнихъ, и драгоцјнностями холмовъ вјчныхъ,',
        16: 'И драгоцјнностями земли, и того, что наполняетъ ее. Благословеніе Явившагося въ терновомъ кустј да пріидетъ на главу Іосифа и на темя наилучшаго изъ братьевъ своихъ,',
        17: 'Крјпость его какъ первороднаго тельца, и роги его, какъ роги буйвола; Ими избодетъ онъ народы всј до предјловъ земли: Это тмы Ефремовы, это тысячи Манассіины.',
        18: 'О Завулонј сказалъ: Веселись Завулонъ, въ путяхъ твоихъ, и Иссахаръ, въ шатрахъ твоихъ.',
        19: 'Созываютъ они людей на гору, тамъ закалаютъ законныя жертвы: Ибо они питаются богатствомъ моря и сокровищами, сокрытыми въ пескј.',
        20: 'О Гадј сказалъ: Благословенъ распространившій Гада, онъ покоитоя какъ левъ, и терзаетъ и руки и голову.',
        21: 'І Онъ избралъ себј первую частъ, тамъ почтенъ удјломъ отъ законодателя. Но пошелъ вмјстј съ главами народа, и исполнилъ правду Господа, и суды съ Израилемъ.',
        22: 'О Данј сказалъ: Данъ молодой левъ, который выбјгаетъ изъ Васана.',
        23: 'О Нефѕалимј сказалъ: Нефѕалимъ насыщенъ благоволеніемъ и исполненъ благословенія Господня; Море и югъ во владјніи его.',
        24: 'О Асирј сказалъ: Благословенъ между сынами Асиръ; Онъ будетъ любимъ братьями своими, и окунетъ въ елей ногу свою.',
        25: 'Желјзо и мјдь запоры твои; Какъ умножаться будутъ дни твои, такъ и богатство твое.',
        26: 'Нјть подобнаго Богу Израилеву, Который по небесамъ принесся на помощь тебе, во славј Своей на облакахъ.',
        27: 'Убјжище твое Богь древній, и ты подъ мышцами вјчными. Онъ прогонитъ враговъ отъ лща твоего, и говоритъ: истребляй!',
        28: 'Израиль живетъ безопасно одинъ, око Іакова видитъ предъ собою землю обильную хлјбомъ и виномъ, и небеса его каплютъ росу.',
        29: 'Благо тебј, Израиль! кто подобенъ тебј? Народъ, спасаемый Господомъ, Который есть щитъ помощи твоей, и мечь славы твоей? Враги твои раболјпствуютъ тебј, и ты попираешь высоты ихъ.',
    },
    34: {
        1: 'И взошелъ Моисей съ равнинъ Моавитскихъ на гору Нево, на вершину Фазги, что противъ Іерихона, и показалъ ему Господь всю землю Галаадъ до самаго Дана,',
        2: 'и всю землю Нефѕалимову и землю Ефремову и Манассіину, и всю землю Іудину, даже до самаго западнаго моря,',
        3: 'и полуденную страну, и равнину долины Іерихона, города Пальмъ, до Сигора.',
        4: 'И сказалъ ему Господь: вотъ земля, о которой Я клялся Аврааму, Исааку и Іакову, говоря: сјмени твоему дамъ ее; Я далъ тебј увидјть ее глазами твоими, но въ нее ты не войдешь,',
        5: 'И умеръ тамъ Моисей рабъ Господень въ землј Моава, по слову Господню.',
        6: 'И погребенъ на долинј въ землј Моава противъ Веѕ-Фегора, и никто не знаетъ мјста погребенія его даже до сего дня.',
        7: 'Моисею было сто двадцать лјтъ, когда онъ умеръ; но зрјніе его не притупилось, и крјность въ немъ не истощилась.',
        8: 'И оплакивали Моисея сыны Израилевы на равнинахъ Моавитскихъ тридцать дней; и прошли дни плача и сјтованіи о Моисеј.',
        9: 'И Іисусъ сынъ Навинъ исполнился духа премудрости, потому что Моисей возложилъ на него руки свои, и повиновались ему сыны Израилевы, и дјлали такъ, какъ повелјлъ Господь Моисею.',
        10: 'Не бывало еще у Израиля пророка такого, какъ Моисей, котораго Господь зналъ лицемъ къ лицу:',
        11: 'если судить по всјмъ знаменіямъ и чудесамъ, которыя послалъ ему Господь сдјлать въ землј Египетсксй надъ Фараономъ, и надъ всјми рабами его, и надъ всею землею его,',
        12: 'и если судитъ по всей оной рукј сильной и по всјмъ великимъ ужасамъ онымъ, которые Моисей сдјлалъ предъ очами Израиля.',
    },
}
